// =====================================================================
// Evangelhos cronológicos — textos dos tópicos da harmonia
// Formato: {p:"Passagem"} abre uma perícope; {v,t,n} é versículo.
// =====================================================================

const EV = window.TEXTOS_SEED["evangelhos"];

EV[1] = [
{p:"Lucas 1:1-4"},
{v:1,t:"Visto que muitos empreenderam compor uma narração dos fatos que entre nós se cumpriram,"},
{v:2,t:"conforme nos transmitiram os que desde o princípio foram testemunhas oculares e ministros da palavra,"},
{v:3,t:"pareceu bem também a mim, depois de investigar tudo cuidadosamente desde a origem, escrever para ti, excelentíssimo Teófilo, uma exposição ordenada,"},
{v:4,t:"para que reconheças a solidez dos ensinamentos que recebeste.",n:"Solidez traduz asphaleia, a firmeza que não deixa lugar a dúvida; ensinamentos verte o verbo katechein, de onde vem catequese."}
];

EV[2] = [
{p:"João 1:1-18"},
{v:1,t:"No princípio era o Verbo, e o Verbo estava junto de Deus, e o Verbo era Deus.",n:"Verbo traduz Logos, a Palavra subsistente de Deus; junto de Deus verte pros ton Theon, que indica não só proximidade, mas orientação viva de pessoa a pessoa."},
{v:2,t:"Ele estava no princípio junto de Deus."},
{v:3,t:"Todas as coisas foram feitas por meio dele, e sem ele nada se fez do que foi feito."},
{v:4,t:"Nele estava a vida, e a vida era a luz dos homens;"},
{v:5,t:"e a luz brilha nas trevas, e as trevas não a apreenderam.",n:"O verbo katalambanein significa ao mesmo tempo compreender e dominar: as trevas nem entenderam a luz nem conseguiram vencê-la."},
{v:6,t:"Houve um homem enviado por Deus, cujo nome era João."},
{v:7,t:"Este veio como testemunha, para dar testemunho da luz, a fim de que todos cressem por meio dele."},
{v:8,t:"Ele não era a luz, mas veio para dar testemunho da luz."},
{v:9,t:"O Verbo era a luz verdadeira, que ilumina todo homem, vindo a este mundo."},
{v:10,t:"Estava no mundo, e o mundo foi feito por meio dele, e o mundo não o conheceu."},
{v:11,t:"Veio para o que era seu, e os seus não o receberam."},
{v:12,t:"Mas a todos os que o receberam deu o poder de se tornarem filhos de Deus: aos que creem no seu nome,"},
{v:13,t:"os quais não nasceram do sangue, nem da vontade da carne, nem da vontade do homem, mas de Deus."},
{v:14,t:"E o Verbo se fez carne e habitou entre nós; e vimos a sua glória, glória como do Unigênito do Pai, cheio de graça e de verdade.",n:"Habitou verte eskenosen, literalmente armou a sua tenda, evocando a tenda do encontro em que Deus habitava no meio de Israel."},
{v:15,t:"João dá testemunho dele e clama: Este era aquele de quem eu disse: o que vem depois de mim passou adiante de mim, porque existia antes de mim."},
{v:16,t:"Da sua plenitude todos nós recebemos, e graça sobre graça."},
{v:17,t:"Porque a Lei foi dada por meio de Moisés; a graça e a verdade vieram por meio de Jesus Cristo."},
{v:18,t:"A Deus, ninguém jamais o viu; o Deus Unigênito, que está no seio do Pai, esse o deu a conhecer."}
];

EV[3] = [
{p:"Mateus 1:1-17"},
{v:1,t:"Livro da origem de Jesus Cristo, filho de Davi, filho de Abraão."},
{v:2,t:"Abraão gerou Isaac; Isaac gerou Jacó; Jacó gerou Judá e seus irmãos;"},
{v:3,t:"Judá gerou de Tamar Farés e Zara; Farés gerou Esrom; Esrom gerou Aram;"},
{v:4,t:"Aram gerou Aminadab; Aminadab gerou Naasson; Naasson gerou Salmon;"},
{v:5,t:"Salmon gerou de Raab Booz; Booz gerou de Rute Obed; Obed gerou Jessé;"},
{v:6,t:"Jessé gerou o rei Davi. Davi gerou Salomão da que fora mulher de Urias;"},
{v:7,t:"Salomão gerou Roboão; Roboão gerou Abias; Abias gerou Asaf;",n:"Os manuscritos gregos mais antigos trazem Asaf aqui e Amós no v. 10, formas que designam os reis Asa e Amon."},
{v:8,t:"Asaf gerou Josafá; Josafá gerou Jorão; Jorão gerou Ozias;"},
{v:9,t:"Ozias gerou Joatão; Joatão gerou Acaz; Acaz gerou Ezequias;"},
{v:10,t:"Ezequias gerou Manassés; Manassés gerou Amós; Amós gerou Josias;"},
{v:11,t:"Josias gerou Jeconias e seus irmãos, no tempo da deportação para a Babilônia."},
{v:12,t:"Depois da deportação para a Babilônia, Jeconias gerou Salatiel; Salatiel gerou Zorobabel;"},
{v:13,t:"Zorobabel gerou Abiud; Abiud gerou Eliacim; Eliacim gerou Azor;"},
{v:14,t:"Azor gerou Sadoc; Sadoc gerou Aquim; Aquim gerou Eliud;"},
{v:15,t:"Eliud gerou Eleazar; Eleazar gerou Matã; Matã gerou Jacó;"},
{v:16,t:"Jacó gerou José, o esposo de Maria, da qual nasceu Jesus, que é chamado Cristo."},
{v:17,t:"Assim, todas as gerações desde Abraão até Davi são catorze gerações; desde Davi até a deportação para a Babilônia, catorze gerações; e desde a deportação para a Babilônia até Cristo, catorze gerações."},
{p:"Lucas 3:23-38"},
{v:23,t:"Jesus, ao começar, tinha cerca de trinta anos, e era, como se julgava, filho de José, filho de Heli,"},
{v:24,t:"filho de Matat, filho de Levi, filho de Melqui, filho de Janai, filho de José,"},
{v:25,t:"filho de Matatias, filho de Amós, filho de Naum, filho de Esli, filho de Nagai,"},
{v:26,t:"filho de Maat, filho de Matatias, filho de Semei, filho de Josec, filho de Jodá,"},
{v:27,t:"filho de Joanã, filho de Resa, filho de Zorobabel, filho de Salatiel, filho de Neri,"},
{v:28,t:"filho de Melqui, filho de Adi, filho de Cosã, filho de Elmadã, filho de Er,"},
{v:29,t:"filho de Jesus, filho de Eliézer, filho de Jorim, filho de Matat, filho de Levi,"},
{v:30,t:"filho de Simeão, filho de Judá, filho de José, filho de Jonã, filho de Eliacim,"},
{v:31,t:"filho de Meleá, filho de Mená, filho de Matatá, filho de Natã, filho de Davi,"},
{v:32,t:"filho de Jessé, filho de Obed, filho de Booz, filho de Sala, filho de Naasson,"},
{v:33,t:"filho de Aminadab, filho de Admin, filho de Arni, filho de Esrom, filho de Farés, filho de Judá,"},
{v:34,t:"filho de Jacó, filho de Isaac, filho de Abraão, filho de Taré, filho de Nacor,"},
{v:35,t:"filho de Seruc, filho de Ragau, filho de Faleg, filho de Éber, filho de Sala,"},
{v:36,t:"filho de Cainã, filho de Arfaxad, filho de Sem, filho de Noé, filho de Lamec,"},
{v:37,t:"filho de Matusalém, filho de Enoc, filho de Jared, filho de Malaleel, filho de Cainã,"},
{v:38,t:"filho de Enós, filho de Set, filho de Adão, filho de Deus."}
];

EV[4] = [
{p:"Lucas 1:5-25"},
{v:5,t:"Houve, nos dias de Herodes, rei da Judeia, um sacerdote chamado Zacarias, da classe de Abias; sua mulher era das filhas de Aarão e chamava-se Isabel."},
{v:6,t:"Ambos eram justos diante de Deus, caminhando irrepreensíveis em todos os mandamentos e preceitos do Senhor."},
{v:7,t:"Não tinham filhos, porque Isabel era estéril, e ambos eram avançados em idade."},
{v:8,t:"Ora, enquanto ele exercia as funções sacerdotais diante de Deus, na ordem da sua classe,"},
{v:9,t:"coube a ele por sorte, segundo o costume do sacerdócio, entrar no santuário do Senhor para oferecer o incenso."},
{v:10,t:"E toda a multidão do povo estava fora, orando, à hora do incenso."},
{v:11,t:"Apareceu a ele um anjo do Senhor, de pé, à direita do altar do incenso."},
{v:12,t:"Ao vê-lo, Zacarias turbou-se, e o temor caiu sobre ele."},
{v:13,t:"Mas o anjo disse a ele: Não temas, Zacarias, porque a tua súplica foi ouvida: Isabel, tua mulher, dará a ti um filho, e tu o chamarás João."},
{v:14,t:"Ele será para ti alegria e júbilo, e muitos se alegrarão com o seu nascimento,"},
{v:15,t:"porque será grande diante do Senhor; não beberá vinho nem bebida fermentada e será cheio do Espírito Santo já desde o ventre de sua mãe;"},
{v:16,t:"e converterá muitos dos filhos de Israel ao Senhor, seu Deus."},
{v:17,t:"Ele caminhará à frente do Senhor com o espírito e o poder de Elias, para converter os corações dos pais aos filhos e os rebeldes à prudência dos justos, a fim de preparar para o Senhor um povo bem disposto."},
{v:18,t:"Zacarias disse ao anjo: Como saberei isso? Pois eu sou velho, e minha mulher é avançada em idade."},
{v:19,t:"O anjo respondeu a ele: Eu sou Gabriel, que assisto diante de Deus, e fui enviado para falar contigo e anunciar a ti esta boa nova."},
{v:20,t:"Eis que ficarás mudo e não poderás falar até o dia em que essas coisas acontecerem, porque não creste nas minhas palavras, que se cumprirão a seu tempo."},
{v:21,t:"O povo estava esperando Zacarias e admirava-se da sua demora no santuário."},
{v:22,t:"Ao sair, não podia falar com eles, e compreenderam que tivera uma visão no santuário; ele fazia sinais para eles e permanecia mudo."},
{v:23,t:"Quando se completaram os dias do seu serviço, voltou para casa."},
{v:24,t:"Depois desses dias, Isabel, sua mulher, concebeu e ocultou-se durante cinco meses, dizendo:"},
{v:25,t:"Assim fez comigo o Senhor, nos dias em que olhou para mim, a fim de tirar a minha vergonha entre os homens."}
];

EV[5] = [
{p:"Lucas 1:26-38"},
{v:26,t:"No sexto mês, o anjo Gabriel foi enviado por Deus a uma cidade da Galileia chamada Nazaré,"},
{v:27,t:"a uma virgem desposada com um homem chamado José, da casa de Davi; e o nome da virgem era Maria."},
{v:28,t:"Entrando onde ela estava, disse: Alegra-te, cheia de graça, o Senhor está contigo.",n:"Cheia de graça verte kecharitomene, particípio perfeito que exprime a plenitude estável da graça já recebida; a Vulgata traduziu gratia plena. A saudação chaire, alegra-te, ecoa os anúncios messiânicos de alegria à filha de Sião."},
{v:29,t:"Ela turbou-se com essas palavras e refletia que saudação seria essa."},
{v:30,t:"O anjo disse a ela: Não temas, Maria, porque encontraste graça diante de Deus."},
{v:31,t:"Eis que conceberás no ventre e darás à luz um filho, e o chamarás Jesus."},
{v:32,t:"Ele será grande, será chamado Filho do Altíssimo, e o Senhor Deus dará a ele o trono de Davi, seu pai;"},
{v:33,t:"reinará para sempre sobre a casa de Jacó, e o seu reino não terá fim."},
{v:34,t:"Maria disse ao anjo: Como será isso, se eu não conheço homem?",n:"Conhecer, no uso bíblico, designa a relação conjugal; o presente do verbo sugere um propósito permanente de virgindade."},
{v:35,t:"O anjo respondeu a ela: O Espírito Santo virá sobre ti, e o poder do Altíssimo te cobrirá com a sua sombra; por isso, o que nascer será santo e será chamado Filho de Deus."},
{v:36,t:"Eis que Isabel, tua parenta, também concebeu um filho na velhice, e este é o sexto mês daquela que chamavam estéril,"},
{v:37,t:"porque para Deus nada é impossível."},
{v:38,t:"Disse então Maria: Eis a serva do Senhor; faça-se em mim segundo a tua palavra. E o anjo retirou-se dela."}
];

EV[6] = [
{p:"Lucas 1:39-56"},
{v:39,t:"Naqueles dias, Maria levantou-se e foi apressadamente para a região montanhosa, a uma cidade de Judá."},
{v:40,t:"Entrou na casa de Zacarias e saudou Isabel."},
{v:41,t:"Quando Isabel ouviu a saudação de Maria, a criança saltou no seu ventre, e Isabel ficou cheia do Espírito Santo."},
{v:42,t:"Com um grande grito, exclamou: Bendita és tu entre as mulheres, e bendito é o fruto do teu ventre!"},
{v:43,t:"Donde me vem que a mãe do meu Senhor venha a mim?"},
{v:44,t:"Pois, quando a voz da tua saudação chegou aos meus ouvidos, a criança saltou de alegria no meu ventre."},
{v:45,t:"Bem-aventurada a que creu, porque se cumprirá o que da parte do Senhor foi dito a ela."},
{v:46,t:"Maria então disse: A minha alma engrandece o Senhor,"},
{v:47,t:"e o meu espírito exulta em Deus, meu Salvador,"},
{v:48,t:"porque olhou para a humildade da sua serva. Eis que, desde agora, todas as gerações me chamarão bem-aventurada,",n:"Humildade verte tapeinosis, que designa antes a condição humilde, a pequenez, do que a virtude da humildade."},
{v:49,t:"porque o Poderoso fez em mim grandes coisas, e santo é o seu nome;"},
{v:50,t:"a sua misericórdia se estende de geração em geração sobre os que o temem."},
{v:51,t:"Manifestou o poder do seu braço, dispersou os soberbos nos pensamentos do seu coração;"},
{v:52,t:"depôs os poderosos dos tronos e exaltou os humildes;"},
{v:53,t:"encheu de bens os famintos e despediu vazios os ricos."},
{v:54,t:"Socorreu Israel, seu servo, recordando a sua misericórdia,"},
{v:55,t:"conforme falara a nossos pais, em favor de Abraão e da sua descendência para sempre."},
{v:56,t:"Maria permaneceu com ela cerca de três meses e voltou para sua casa."}
];

EV[7] = [
{p:"Lucas 1:57-80"},
{v:57,t:"Completou-se para Isabel o tempo de dar à luz, e ela teve um filho."},
{v:58,t:"Os vizinhos e parentes ouviram que o Senhor usara com ela de grande misericórdia e alegravam-se com ela."},
{v:59,t:"No oitavo dia, vieram circuncidar o menino e queriam chamá-lo Zacarias, com o nome de seu pai."},
{v:60,t:"Mas sua mãe respondeu: Não; ele será chamado João."},
{v:61,t:"Disseram a ela: Não há ninguém na tua parentela que tenha esse nome."},
{v:62,t:"E perguntavam por sinais ao pai como queria que ele se chamasse."},
{v:63,t:"Ele pediu uma tabuinha e escreveu: João é o seu nome. E todos se admiraram."},
{v:64,t:"No mesmo instante, abriu-se a sua boca e soltou-se a sua língua, e falava, bendizendo a Deus."},
{v:65,t:"O temor apoderou-se de todos os seus vizinhos, e por toda a região montanhosa da Judeia se comentavam todas essas coisas;"},
{v:66,t:"todos os que as ouviam guardavam-nas no coração, dizendo: Que virá a ser este menino? Pois a mão do Senhor estava com ele."},
{v:67,t:"Zacarias, seu pai, ficou cheio do Espírito Santo e profetizou, dizendo:"},
{v:68,t:"Bendito o Senhor, Deus de Israel, porque visitou e redimiu o seu povo,"},
{v:69,t:"e suscitou para nós uma força de salvação na casa de Davi, seu servo,",n:"Literalmente, um chifre de salvação: imagem hebraica do poder invencível."},
{v:70,t:"como falara pela boca dos seus santos profetas desde a antiguidade:"},
{v:71,t:"salvação dos nossos inimigos e da mão de todos os que nos odeiam;"},
{v:72,t:"para fazer misericórdia com os nossos pais e recordar a sua santa aliança,"},
{v:73,t:"o juramento que jurou a Abraão, nosso pai, de conceder a nós"},
{v:74,t:"que, libertados da mão dos inimigos, o sirvamos sem temor,"},
{v:75,t:"em santidade e justiça, diante dele, todos os nossos dias."},
{v:76,t:"E tu, menino, serás chamado profeta do Altíssimo, porque irás à frente do Senhor para preparar os seus caminhos,"},
{v:77,t:"para dar ao seu povo o conhecimento da salvação, no perdão dos seus pecados,"},
{v:78,t:"pelas entranhas de misericórdia do nosso Deus, com que nos visitará o Sol nascente do alto,",n:"Sol nascente traduz anatole, termo que na versão grega do Antigo Testamento verte também o Germe messiânico anunciado pelos profetas."},
{v:79,t:"para iluminar os que jazem nas trevas e na sombra da morte e dirigir os nossos passos no caminho da paz."},
{v:80,t:"O menino crescia e fortalecia-se em espírito, e viveu nos desertos até o dia da sua manifestação a Israel."}
];

EV[8] = [
{p:"Mateus 1:18-25"},
{v:18,t:"A origem de Jesus Cristo foi assim: Maria, sua mãe, estava desposada com José; antes de coabitarem, achou-se grávida por obra do Espírito Santo.",n:"O desposório judaico já constituía vínculo matrimonial verdadeiro, embora a esposa ainda não vivesse na casa do esposo."},
{v:19,t:"José, seu esposo, sendo justo e não querendo expô-la publicamente, resolveu deixá-la em segredo."},
{v:20,t:"Enquanto pensava nisso, eis que um anjo do Senhor apareceu a ele em sonho, dizendo: José, filho de Davi, não temas receber Maria, tua esposa, pois o que nela foi gerado vem do Espírito Santo."},
{v:21,t:"Ela dará à luz um filho, e tu o chamarás Jesus, porque ele salvará o seu povo dos seus pecados.",n:"Jesus, em hebraico Yeshua, significa o Senhor salva."},
{v:22,t:"Tudo isso aconteceu para que se cumprisse o que o Senhor dissera pelo profeta:"},
{v:23,t:"Eis que a virgem conceberá e dará à luz um filho, e o chamarão Emanuel, que significa: Deus conosco."},
{v:24,t:"Despertando do sono, José fez como o anjo do Senhor ordenara e recebeu a sua esposa."},
{v:25,t:"E não a conhecia, até que ela deu à luz um filho; e ele o chamou Jesus.",n:"A expressão semítica até que afirma apenas o que houve antes do parto, sem nada dizer sobre o que se seguiu; não contradiz a virgindade perpétua de Maria."}
];

EV[9] = [
{p:"Lucas 2:1-7"},
{v:1,t:"Naqueles dias, saiu um decreto de César Augusto para que se recenseasse toda a terra."},
{v:2,t:"Este primeiro recenseamento foi feito quando Quirino era governador da Síria."},
{v:3,t:"E todos iam recensear-se, cada um à sua cidade."},
{v:4,t:"José também subiu da Galileia, da cidade de Nazaré, para a Judeia, à cidade de Davi, chamada Belém, por ser da casa e da família de Davi,"},
{v:5,t:"para recensear-se com Maria, sua esposa, que estava grávida."},
{v:6,t:"Enquanto estavam ali, completaram-se os dias de ela dar à luz,"},
{v:7,t:"e deu à luz o seu filho primogênito; envolveu-o em faixas e reclinou-o numa manjedoura, porque não havia lugar para eles na hospedaria.",n:"Primogênito é título legal do primeiro nascido, com os direitos e deveres previstos na Lei, e não implica que tenham nascido outros filhos depois."}
];

EV[10] = [
{p:"Lucas 2:8-20"},
{v:8,t:"Havia naquela região pastores que viviam nos campos e guardavam de noite os turnos de vigília junto ao seu rebanho."},
{v:9,t:"Um anjo do Senhor apareceu junto deles, e a glória do Senhor os envolveu de luz, e temeram com grande temor."},
{v:10,t:"O anjo disse a eles: Não temais; eis que eu vos anuncio uma grande alegria, que será para todo o povo:"},
{v:11,t:"nasceu para vós hoje, na cidade de Davi, um Salvador, que é Cristo, o Senhor."},
{v:12,t:"E isto vos servirá de sinal: encontrareis um recém-nascido envolto em faixas e deitado numa manjedoura."},
{v:13,t:"De repente, juntou-se ao anjo uma multidão do exército celeste, que louvava a Deus, dizendo:"},
{v:14,t:"Glória a Deus nas alturas, e paz na terra aos homens do seu agrado.",n:"Do seu agrado verte eudokias: os homens que são objeto da benevolência divina, e não os homens de boa vontade da antiga versão latina."},
{v:15,t:"Quando os anjos se retiraram deles para o céu, os pastores diziam uns aos outros: Vamos até Belém e vejamos o que aconteceu, o que o Senhor nos deu a conhecer."},
{v:16,t:"Foram apressadamente e encontraram Maria, José e o recém-nascido deitado na manjedoura."},
{v:17,t:"Ao verem, contaram o que se dissera a eles a respeito daquele menino."},
{v:18,t:"E todos os que ouviram admiraram-se do que os pastores diziam."},
{v:19,t:"Maria, porém, conservava todas essas coisas, meditando-as no seu coração."},
{v:20,t:"Os pastores voltaram, glorificando e louvando a Deus por tudo o que tinham ouvido e visto, conforme se dissera a eles."}
];

EV[11] = [
{p:"Lucas 2:21"},
{v:21,t:"Quando se completaram os oito dias para a circuncisão do menino, foi chamado Jesus, nome que o anjo dissera antes de ele ser concebido no ventre."}
];

EV[12] = [
{p:"Lucas 2:22-38"},
{v:22,t:"Quando se completaram os dias da purificação deles, segundo a Lei de Moisés, levaram-no a Jerusalém para apresentá-lo ao Senhor,"},
{v:23,t:"como está escrito na Lei do Senhor: Todo primogênito varão será consagrado ao Senhor,"},
{v:24,t:"e para oferecer em sacrifício, segundo o que se diz na Lei do Senhor, um par de rolas ou dois pombinhos.",n:"Era a oferta dos pobres, prevista para quem não podia apresentar um cordeiro."},
{v:25,t:"Havia em Jerusalém um homem chamado Simeão; era justo e piedoso, esperava a consolação de Israel, e o Espírito Santo estava sobre ele."},
{v:26,t:"Fora revelado a ele pelo Espírito Santo que não veria a morte antes de ver o Cristo do Senhor."},
{v:27,t:"Movido pelo Espírito, foi ao Templo; e, quando os pais trouxeram o menino Jesus para cumprirem a seu respeito o costume da Lei,"},
{v:28,t:"ele o tomou nos braços e bendisse a Deus, dizendo:"},
{v:29,t:"Agora, Senhor, deixas ir em paz o teu servo, segundo a tua palavra,"},
{v:30,t:"porque os meus olhos viram a tua salvação,"},
{v:31,t:"que preparaste diante de todos os povos:"},
{v:32,t:"luz para iluminar as nações e glória do teu povo Israel."},
{v:33,t:"Seu pai e sua mãe admiravam-se do que se dizia a respeito dele."},
{v:34,t:"Simeão os abençoou e disse a Maria, sua mãe: Eis que este menino está posto para queda e reerguimento de muitos em Israel e como sinal de contradição"},
{v:35,t:"— e uma espada traspassará a tua própria alma —, para que se revelem os pensamentos de muitos corações."},
{v:36,t:"Havia também uma profetisa, Ana, filha de Fanuel, da tribo de Aser; era de idade muito avançada: vivera com o marido sete anos desde a sua virgindade"},
{v:37,t:"e era viúva de oitenta e quatro anos; não se afastava do Templo, servindo a Deus noite e dia com jejuns e orações."},
{v:38,t:"Chegando naquela mesma hora, louvava a Deus e falava do menino a todos os que esperavam a redenção de Jerusalém."}
];

EV[13] = [
{p:"Mateus 2:1-12"},
{v:1,t:"Tendo Jesus nascido em Belém da Judeia, nos dias do rei Herodes, eis que magos vindos do oriente chegaram a Jerusalém,",n:"Magos designava sábios orientais dedicados à observação dos astros; o número três é dedução posterior, a partir dos três presentes."},
{v:2,t:"dizendo: Onde está o rei dos judeus que acaba de nascer? Vimos a sua estrela no oriente e viemos adorá-lo.",n:"No oriente pode também traduzir-se no seu surgir: viram a estrela levantar-se."},
{v:3,t:"Ao ouvir isso, o rei Herodes perturbou-se, e toda Jerusalém com ele;"},
{v:4,t:"e, reunindo todos os príncipes dos sacerdotes e os escribas do povo, perguntava a eles onde havia de nascer o Cristo."},
{v:5,t:"Eles responderam: Em Belém da Judeia, pois assim está escrito pelo profeta:"},
{v:6,t:"E tu, Belém, terra de Judá, de modo algum és a menor entre as principais cidades de Judá, porque de ti sairá o chefe que apascentará Israel, meu povo."},
{v:7,t:"Então Herodes chamou os magos em segredo e averiguou com eles o tempo em que a estrela aparecera;"},
{v:8,t:"e, enviando-os a Belém, disse: Ide e informai-vos com exatidão sobre o menino; quando o encontrardes, avisai-me, para que eu também vá adorá-lo."},
{v:9,t:"Depois de ouvirem o rei, partiram; e eis que a estrela que tinham visto no oriente ia adiante deles, até parar sobre o lugar onde estava o menino."},
{v:10,t:"Ao verem a estrela, alegraram-se com grandíssima alegria."},
{v:11,t:"Entrando na casa, viram o menino com Maria, sua mãe; prostrando-se, adoraram-no; e, abrindo os seus tesouros, ofereceram a ele presentes: ouro, incenso e mirra."},
{v:12,t:"Avisados em sonho para não voltarem a Herodes, retiraram-se por outro caminho para a sua região."}
];

EV[14] = [
{p:"Mateus 2:13-18"},
{v:13,t:"Depois que eles partiram, eis que um anjo do Senhor apareceu em sonho a José, dizendo: Levanta-te, toma o menino e sua mãe, foge para o Egito e fica lá até que eu te avise, porque Herodes vai procurar o menino para matá-lo."},
{v:14,t:"Ele levantou-se, tomou de noite o menino e sua mãe e retirou-se para o Egito,"},
{v:15,t:"onde ficou até a morte de Herodes, para que se cumprisse o que o Senhor dissera pelo profeta: Do Egito chamei o meu filho."},
{v:16,t:"Então Herodes, vendo que fora enganado pelos magos, irritou-se profundamente e mandou matar todos os meninos de Belém e de todo o seu território, de dois anos para baixo, conforme o tempo que averiguara com os magos."},
{v:17,t:"Cumpriu-se então o que fora dito pelo profeta Jeremias:"},
{v:18,t:"Uma voz se ouviu em Ramá, pranto e grande lamento: é Raquel que chora os seus filhos e não quer ser consolada, porque já não existem."}
];

EV[15] = [
{p:"Mateus 2:19-23"},
{v:19,t:"Morto Herodes, eis que um anjo do Senhor apareceu em sonho a José, no Egito,"},
{v:20,t:"dizendo: Levanta-te, toma o menino e sua mãe e vai para a terra de Israel, pois morreram os que atentavam contra a vida do menino."},
{v:21,t:"Ele levantou-se, tomou o menino e sua mãe e entrou na terra de Israel."},
{v:22,t:"Mas, ouvindo que Arquelau reinava na Judeia em lugar de Herodes, seu pai, teve medo de ir para lá; avisado em sonho, retirou-se para a região da Galileia"},
{v:23,t:"e foi morar numa cidade chamada Nazaré, para que se cumprisse o que fora dito pelos profetas: Será chamado Nazareno.",n:"Nenhum profeta traz literalmente essa frase; o evangelista resume um tema profético, talvez com alusão a netser, o rebento do tronco de Jessé."},
{p:"Lucas 2:39-40"},
{v:39,t:"Quando cumpriram tudo segundo a Lei do Senhor, voltaram para a Galileia, para a sua cidade de Nazaré."},
{v:40,t:"O menino crescia e fortalecia-se, cheio de sabedoria, e a graça de Deus estava sobre ele."}
];

EV[16] = [
{p:"Lucas 2:41-50"},
{v:41,t:"Seus pais iam todos os anos a Jerusalém, para a festa da Páscoa."},
{v:42,t:"Quando ele completou doze anos, subiram, segundo o costume da festa;"},
{v:43,t:"terminados aqueles dias, ao voltarem, o menino Jesus ficou em Jerusalém, sem que os seus pais o soubessem."},
{v:44,t:"Pensando que ele estava na caravana, caminharam um dia e procuravam-no entre os parentes e conhecidos;"},
{v:45,t:"não o encontrando, voltaram a Jerusalém à sua procura."},
{v:46,t:"Depois de três dias, encontraram-no no Templo, sentado no meio dos doutores, ouvindo-os e interrogando-os;"},
{v:47,t:"e todos os que o ouviam pasmavam da sua inteligência e das suas respostas."},
{v:48,t:"Ao vê-lo, ficaram atônitos, e sua mãe disse a ele: Filho, por que agiste assim conosco? Eis que teu pai e eu, aflitos, te procurávamos."},
{v:49,t:"Ele respondeu: Por que me procuráveis? Não sabíeis que devo estar nas coisas de meu Pai?",n:"A expressão grega admite dois sentidos, ambos verdadeiros: nas coisas de meu Pai ou na casa de meu Pai."},
{v:50,t:"Mas eles não compreenderam a palavra que dissera a eles."}
];

EV[17] = [
{p:"Lucas 2:51-52"},
{v:51,t:"Desceu com eles, foi para Nazaré e era submisso a eles. Sua mãe conservava todas essas coisas no coração."},
{v:52,t:"E Jesus crescia em sabedoria, em estatura e em graça, diante de Deus e dos homens."}
];

EV[18] = [
{p:"Mateus 3:1-12"},
{v:1,t:"Naqueles dias, apareceu João Batista, pregando no deserto da Judeia"},
{v:2,t:"e dizendo: Convertei-vos, porque está próximo o Reino dos Céus.",n:"Convertei-vos verte metanoeite: mudança profunda da mente e do coração, e não apenas penitência exterior."},
{v:3,t:"Este é aquele de quem falou o profeta Isaías: Voz do que clama no deserto: Preparai o caminho do Senhor, endireitai as suas veredas."},
{v:4,t:"João usava uma veste de pelos de camelo e um cinto de couro à volta dos rins; o seu alimento eram gafanhotos e mel silvestre."},
{v:5,t:"Então saíam ao seu encontro Jerusalém, toda a Judeia e toda a região do Jordão,"},
{v:6,t:"e eram batizados por ele no rio Jordão, confessando os seus pecados."},
{v:7,t:"Vendo que muitos fariseus e saduceus vinham ao seu batismo, disse a eles: Raça de víboras, quem vos ensinou a fugir da ira que está para vir?"},
{v:8,t:"Produzi, pois, fruto digno da conversão"},
{v:9,t:"e não penseis que basta dizer dentro de vós: Temos Abraão por pai. Pois eu vos digo que Deus pode suscitar destas pedras filhos a Abraão."},
{v:10,t:"O machado já está posto à raiz das árvores; toda árvore que não produz bom fruto será cortada e lançada ao fogo."},
{v:11,t:"Eu vos batizo com água para a conversão; mas aquele que vem depois de mim é mais forte do que eu, e eu não sou digno de levar as suas sandálias: ele vos batizará no Espírito Santo e no fogo."},
{v:12,t:"Tem na mão a pá de joeirar e limpará a sua eira: recolherá o seu trigo no celeiro, mas queimará a palha em fogo inextinguível."},
{p:"Marcos 1:1-8"},
{v:1,t:"Princípio do Evangelho de Jesus Cristo, Filho de Deus."},
{v:2,t:"Como está escrito no profeta Isaías: Eis que envio o meu mensageiro diante da tua face; ele preparará o teu caminho.",n:"A citação combina Malaquias e Êxodo com Isaías; Marcos a atribui em bloco ao profeta maior."},
{v:3,t:"Voz do que clama no deserto: Preparai o caminho do Senhor, endireitai as suas veredas."},
{v:4,t:"Apareceu João no deserto, batizando e pregando um batismo de conversão para o perdão dos pecados."},
{v:5,t:"Saía ao seu encontro toda a região da Judeia e todos os habitantes de Jerusalém, e eram batizados por ele no rio Jordão, confessando os seus pecados."},
{v:6,t:"João vestia-se de pelos de camelo, com um cinto de couro à volta dos rins, e comia gafanhotos e mel silvestre."},
{v:7,t:"E pregava, dizendo: Depois de mim vem o que é mais forte do que eu, diante de quem não sou digno de me inclinar para desatar a correia das suas sandálias."},
{v:8,t:"Eu vos batizei com água, mas ele vos batizará no Espírito Santo."},
{p:"Lucas 3:1-18"},
{v:1,t:"No décimo quinto ano do governo de Tibério César, sendo Pôncio Pilatos governador da Judeia, Herodes tetrarca da Galileia, Filipe, seu irmão, tetrarca da região da Itureia e da Traconítide, e Lisânias tetrarca da Abilene,"},
{v:2,t:"sob os sumos sacerdotes Anás e Caifás, a palavra de Deus veio a João, filho de Zacarias, no deserto."},
{v:3,t:"Ele percorreu toda a região do Jordão, pregando um batismo de conversão para o perdão dos pecados,"},
{v:4,t:"como está escrito no livro das palavras do profeta Isaías: Voz do que clama no deserto: Preparai o caminho do Senhor, endireitai as suas veredas."},
{v:5,t:"Todo vale será aterrado, todo monte e colina serão abaixados; os caminhos tortuosos se tornarão retos, e os escabrosos, planos;"},
{v:6,t:"e toda carne verá a salvação de Deus."},
{v:7,t:"Dizia então às multidões que saíam para ser batizadas por ele: Raça de víboras, quem vos ensinou a fugir da ira que está para vir?"},
{v:8,t:"Produzi, pois, frutos dignos da conversão e não comeceis a dizer dentro de vós: Temos Abraão por pai. Pois eu vos digo que Deus pode suscitar destas pedras filhos a Abraão."},
{v:9,t:"O machado já está posto à raiz das árvores; toda árvore que não produz bom fruto será cortada e lançada ao fogo."},
{v:10,t:"As multidões perguntavam a ele: Que devemos fazer?"},
{v:11,t:"Ele respondia: Quem tem duas túnicas reparta com quem não tem, e quem tem o que comer faça o mesmo."},
{v:12,t:"Vieram também publicanos para ser batizados e disseram a ele: Mestre, que devemos fazer?"},
{v:13,t:"Ele respondeu: Não exijais nada além do que vos foi fixado."},
{v:14,t:"Também soldados perguntavam: E nós, que devemos fazer? Disse a eles: Não pratiqueis extorsão contra ninguém, não denuncieis falsamente e contentai-vos com o vosso soldo."},
{v:15,t:"Como o povo estava na expectativa e todos se perguntavam no coração se João não seria o Cristo,"},
{v:16,t:"João respondeu a todos: Eu vos batizo com água, mas vem aquele que é mais forte do que eu, e eu não sou digno de desatar a correia das suas sandálias: ele vos batizará no Espírito Santo e no fogo."},
{v:17,t:"Tem na mão a pá de joeirar para limpar a sua eira e recolher o trigo no seu celeiro; a palha, porém, ele a queimará em fogo inextinguível."},
{v:18,t:"Assim, com muitas outras exortações, anunciava ao povo a boa nova."}
];

EV[19] = [
{p:"Mateus 3:13-17"},
{v:13,t:"Então Jesus veio da Galileia ao Jordão, ao encontro de João, para ser batizado por ele."},
{v:14,t:"João procurava impedi-lo, dizendo: Eu é que preciso ser batizado por ti, e tu vens a mim?"},
{v:15,t:"Jesus respondeu: Deixa por agora, pois assim nos convém cumprir toda a justiça. Então João o deixou."},
{v:16,t:"Batizado, Jesus saiu logo da água; e eis que os céus se abriram, e ele viu o Espírito de Deus descer como pomba e vir sobre ele."},
{v:17,t:"E uma voz dos céus dizia: Este é o meu Filho amado, em quem me comprazo."},
{p:"Marcos 1:9-11"},
{v:9,t:"Naqueles dias, Jesus veio de Nazaré da Galileia e foi batizado por João no Jordão."},
{v:10,t:"Logo ao sair da água, viu os céus rasgarem-se e o Espírito descer sobre ele como pomba."},
{v:11,t:"E dos céus veio uma voz: Tu és o meu Filho amado, em ti me comprazo."},
{p:"Lucas 3:21-22"},
{v:21,t:"Quando todo o povo era batizado, também Jesus foi batizado; e, enquanto orava, o céu se abriu,"},
{v:22,t:"e o Espírito Santo desceu sobre ele em forma corpórea, como pomba; e veio do céu uma voz: Tu és o meu Filho amado, em ti me comprazo."}
];

EV[20] = [
{p:"Mateus 4:1-11"},
{v:1,t:"Então Jesus foi conduzido pelo Espírito ao deserto, para ser tentado pelo diabo."},
{v:2,t:"Depois de jejuar quarenta dias e quarenta noites, teve fome."},
{v:3,t:"O tentador aproximou-se e disse a ele: Se és Filho de Deus, manda que estas pedras se tornem pães."},
{v:4,t:"Ele respondeu: Está escrito: Não só de pão viverá o homem, mas de toda palavra que sai da boca de Deus."},
{v:5,t:"Então o diabo o levou à Cidade Santa, colocou-o sobre o pináculo do Templo"},
{v:6,t:"e disse a ele: Se és Filho de Deus, lança-te daqui abaixo, pois está escrito: Aos seus anjos dará ordens a teu respeito, e eles te sustentarão nas mãos, para que não tropeces em alguma pedra."},
{v:7,t:"Jesus respondeu: Também está escrito: Não tentarás o Senhor, teu Deus."},
{v:8,t:"De novo o diabo o levou a um monte muito alto, mostrou a ele todos os reinos do mundo e a sua glória"},
{v:9,t:"e disse: Tudo isto darei a ti, se, prostrado, me adorares."},
{v:10,t:"Então Jesus disse a ele: Vai-te, Satanás, pois está escrito: Adorarás o Senhor, teu Deus, e só a ele prestarás culto."},
{v:11,t:"Então o diabo o deixou; e eis que os anjos se aproximaram e o serviam."},
{p:"Marcos 1:12-13"},
{v:12,t:"Logo depois, o Espírito o impeliu para o deserto."},
{v:13,t:"E esteve no deserto quarenta dias, tentado por Satanás; vivia entre as feras, e os anjos o serviam."},
{p:"Lucas 4:1-13"},
{v:1,t:"Jesus, cheio do Espírito Santo, voltou do Jordão e era conduzido pelo Espírito no deserto,"},
{v:2,t:"durante quarenta dias, sendo tentado pelo diabo. Não comeu nada naqueles dias e, terminados eles, teve fome."},
{v:3,t:"O diabo disse a ele: Se és Filho de Deus, manda que esta pedra se torne pão."},
{v:4,t:"Jesus respondeu: Está escrito: Não só de pão viverá o homem."},
{v:5,t:"Levando-o ao alto, o diabo mostrou a ele, num instante, todos os reinos da terra"},
{v:6,t:"e disse: Darei a ti todo este poder e a glória destes reinos, porque foram entregues a mim e eu os dou a quem quero."},
{v:7,t:"Portanto, se te prostrares diante de mim, tudo será teu."},
{v:8,t:"Jesus respondeu: Está escrito: Adorarás o Senhor, teu Deus, e só a ele prestarás culto."},
{v:9,t:"Então o levou a Jerusalém, colocou-o sobre o pináculo do Templo e disse: Se és Filho de Deus, lança-te daqui abaixo,"},
{v:10,t:"pois está escrito: Aos seus anjos dará ordens a teu respeito, para que te guardem;"},
{v:11,t:"e: Eles te sustentarão nas mãos, para que não tropeces em alguma pedra."},
{v:12,t:"Jesus respondeu: Está dito: Não tentarás o Senhor, teu Deus."},
{v:13,t:"Terminada toda tentação, o diabo afastou-se dele até o tempo oportuno."}
];

EV[21] = [
{p:"João 1:19-34"},
{v:19,t:"Este é o testemunho de João, quando os judeus enviaram de Jerusalém sacerdotes e levitas para perguntarem a ele: Quem és tu?"},
{v:20,t:"Ele confessou e não negou; confessou: Eu não sou o Cristo."},
{v:21,t:"Perguntaram: Então quem és? És Elias? Disse: Não sou. És o Profeta? Respondeu: Não.",n:"O Profeta é a figura anunciada por Moisés no Deuteronômio, esperada para os tempos messiânicos."},
{v:22,t:"Disseram então: Quem és? Para darmos resposta aos que nos enviaram, que dizes de ti mesmo?"},
{v:23,t:"Declarou: Eu sou a voz do que clama no deserto: Endireitai o caminho do Senhor, como disse o profeta Isaías."},
{v:24,t:"Os enviados eram dos fariseus"},
{v:25,t:"e perguntaram: Por que batizas, então, se não és o Cristo, nem Elias, nem o Profeta?"},
{v:26,t:"João respondeu: Eu batizo com água; no meio de vós está quem vós não conheceis,"},
{v:27,t:"aquele que vem depois de mim, de quem não sou digno de desatar a correia da sandália."},
{v:28,t:"Isso aconteceu em Betânia, além do Jordão, onde João estava batizando."},
{v:29,t:"No dia seguinte, viu Jesus vir ao seu encontro e disse: Eis o Cordeiro de Deus, que tira o pecado do mundo.",n:"O verbo airein significa tirar e carregar: o Cordeiro remove o pecado tomando-o sobre si, como o Servo de Isaías."},
{v:30,t:"Este é aquele de quem eu disse: Depois de mim vem um homem que passou adiante de mim, porque existia antes de mim."},
{v:31,t:"Eu não o conhecia, mas foi para que ele fosse manifestado a Israel que eu vim batizar com água."},
{v:32,t:"E João deu testemunho, dizendo: Vi o Espírito descer do céu como pomba e permanecer sobre ele."},
{v:33,t:"Eu não o conhecia, mas quem me enviou a batizar com água disse a mim: Aquele sobre quem vires o Espírito descer e permanecer, esse é o que batiza no Espírito Santo."},
{v:34,t:"E eu vi e dou testemunho: este é o Filho de Deus."}
];

EV[22] = [
{p:"João 1:35-51"},
{v:35,t:"No dia seguinte, João estava de novo ali com dois dos seus discípulos"},
{v:36,t:"e, fixando o olhar em Jesus, que passava, disse: Eis o Cordeiro de Deus."},
{v:37,t:"Os dois discípulos ouviram-no falar e seguiram Jesus."},
{v:38,t:"Jesus voltou-se e, vendo que o seguiam, perguntou: Que procurais? Disseram: Rabi — que quer dizer Mestre —, onde moras?"},
{v:39,t:"Respondeu: Vinde e vede. Foram, viram onde morava e permaneceram com ele aquele dia; era por volta da hora décima.",n:"Cerca de quatro horas da tarde."},
{v:40,t:"André, irmão de Simão Pedro, era um dos dois que tinham ouvido João e seguido Jesus."},
{v:41,t:"Ele encontrou primeiro o seu irmão Simão e disse: Encontramos o Messias — que quer dizer Cristo —"},
{v:42,t:"e o levou a Jesus. Fixando nele o olhar, Jesus disse: Tu és Simão, filho de João; tu te chamarás Cefas — que quer dizer Pedra."},
{v:43,t:"No dia seguinte, Jesus resolveu partir para a Galileia. Encontrou Filipe e disse a ele: Segue-me."},
{v:44,t:"Filipe era de Betsaida, a cidade de André e de Pedro."},
{v:45,t:"Filipe encontrou Natanael e disse: Encontramos aquele de quem escreveram Moisés, na Lei, e os profetas: Jesus, filho de José, de Nazaré."},
{v:46,t:"Natanael disse: De Nazaré pode sair algo de bom? Filipe respondeu: Vem e vê."},
{v:47,t:"Jesus viu Natanael vir ao seu encontro e disse dele: Eis um verdadeiro israelita, em quem não há falsidade."},
{v:48,t:"Natanael perguntou: Donde me conheces? Jesus respondeu: Antes de Filipe te chamar, eu te vi, quando estavas debaixo da figueira."},
{v:49,t:"Natanael respondeu: Rabi, tu és o Filho de Deus, tu és o Rei de Israel!"},
{v:50,t:"Jesus disse: Crês porque eu disse que te vi debaixo da figueira? Verás coisas maiores do que estas."},
{v:51,t:"E acrescentou: Em verdade, em verdade vos digo: vereis o céu aberto e os anjos de Deus subirem e descerem sobre o Filho do Homem.",n:"Alusão à escada de Jacó: Cristo é o novo lugar do encontro entre o céu e a terra."}
];

EV[23] = [
{p:"João 2:1-12"},
{v:1,t:"Três dias depois, houve umas bodas em Caná da Galileia, e a mãe de Jesus estava ali."},
{v:2,t:"Também Jesus foi convidado para as bodas, com os seus discípulos."},
{v:3,t:"Faltando o vinho, a mãe de Jesus disse a ele: Não têm vinho."},
{v:4,t:"Jesus respondeu: Que há entre mim e ti, mulher? Ainda não chegou a minha hora.",n:"A expressão semítica que há entre mim e ti marca distância entre planos, sem aspereza; mulher, no uso de João, é tratamento solene, que reaparecerá junto à cruz."},
{v:5,t:"Sua mãe disse aos que serviam: Fazei tudo o que ele vos disser."},
{v:6,t:"Havia ali seis talhas de pedra, destinadas à purificação dos judeus, cada uma com capacidade de duas ou três medidas.",n:"Cada medida, o metretes, equivalia a cerca de quarenta litros."},
{v:7,t:"Jesus disse a eles: Enchei as talhas de água. E encheram-nas até em cima."},
{v:8,t:"Então disse: Tirai agora e levai ao mestre-sala. E levaram."},
{v:9,t:"Quando o mestre-sala provou a água transformada em vinho — e não sabia donde vinha, mas sabiam os que serviam, que tinham tirado a água —, chamou o esposo"},
{v:10,t:"e disse: Todo homem serve primeiro o vinho bom e, quando já beberam bastante, o inferior; tu guardaste o vinho bom até agora."},
{v:11,t:"Este princípio dos sinais, Jesus o fez em Caná da Galileia; manifestou a sua glória, e os seus discípulos creram nele."},
{v:12,t:"Depois disso, desceu a Cafarnaum com sua mãe, seus irmãos e seus discípulos, e permaneceram ali poucos dias.",n:"Irmãos, no uso semítico, abrange os parentes próximos, como primos; nada diz de outros filhos de Maria."}
];

EV[24] = [
{p:"João 2:13-25"},
{v:13,t:"Estava próxima a Páscoa dos judeus, e Jesus subiu a Jerusalém."},
{v:14,t:"Encontrou no Templo os vendedores de bois, ovelhas e pombas, e os cambistas sentados;"},
{v:15,t:"e, fazendo um chicote de cordas, expulsou todos do Templo, com as ovelhas e os bois; espalhou o dinheiro dos cambistas e derrubou as mesas;"},
{v:16,t:"e aos que vendiam pombas disse: Tirai isto daqui; não façais da casa de meu Pai uma casa de comércio."},
{v:17,t:"Os seus discípulos lembraram-se de que está escrito: O zelo da tua casa me devorará."},
{v:18,t:"Os judeus então disseram a ele: Que sinal nos mostras, para fazeres essas coisas?"},
{v:19,t:"Jesus respondeu: Destruí este templo, e em três dias eu o levantarei."},
{v:20,t:"Os judeus disseram: Em quarenta e seis anos foi construído este templo, e tu o levantarás em três dias?"},
{v:21,t:"Mas ele falava do templo do seu corpo."},
{v:22,t:"Por isso, quando ressuscitou dos mortos, os seus discípulos lembraram-se de que ele dissera isso e creram na Escritura e na palavra que Jesus dissera."},
{v:23,t:"Enquanto estava em Jerusalém, na festa da Páscoa, muitos creram no seu nome, vendo os sinais que fazia."},
{v:24,t:"Mas Jesus não se confiava a eles, porque os conhecia a todos"},
{v:25,t:"e não precisava de que alguém desse testemunho sobre o homem, pois ele sabia o que há no homem."}
];

EV[25] = [
{p:"João 3:1-21"},
{v:1,t:"Havia entre os fariseus um homem chamado Nicodemos, um dos chefes dos judeus."},
{v:2,t:"Ele foi ter com Jesus de noite e disse: Rabi, sabemos que vieste de Deus como mestre, pois ninguém pode fazer os sinais que tu fazes, se Deus não estiver com ele."},
{v:3,t:"Jesus respondeu: Em verdade, em verdade te digo: quem não nascer do alto não pode ver o Reino de Deus.",n:"O advérbio anothen significa ao mesmo tempo do alto e de novo; o duplo sentido sustenta todo o diálogo."},
{v:4,t:"Nicodemos perguntou: Como pode um homem nascer, sendo velho? Pode entrar segunda vez no ventre de sua mãe e nascer?"},
{v:5,t:"Jesus respondeu: Em verdade, em verdade te digo: quem não nascer da água e do Espírito não pode entrar no Reino de Deus."},
{v:6,t:"O que nasceu da carne é carne, e o que nasceu do Espírito é espírito."},
{v:7,t:"Não te admires de eu te dizer: é necessário nascerdes do alto."},
{v:8,t:"O vento sopra onde quer, e ouves a sua voz, mas não sabes donde vem nem para onde vai; assim é todo aquele que nasceu do Espírito.",n:"Em grego, pneuma designa tanto o vento quanto o Espírito: a frase joga com os dois sentidos."},
{v:9,t:"Nicodemos perguntou: Como pode ser isso?"},
{v:10,t:"Jesus respondeu: Tu és mestre em Israel e não sabes isso?"},
{v:11,t:"Em verdade, em verdade te digo: nós falamos do que sabemos e damos testemunho do que vimos, mas vós não recebeis o nosso testemunho."},
{v:12,t:"Se vos falei das coisas terrenas e não credes, como crereis, se eu vos falar das celestes?"},
{v:13,t:"Ninguém subiu ao céu senão aquele que desceu do céu, o Filho do Homem."},
{v:14,t:"E, como Moisés levantou a serpente no deserto, assim é necessário que o Filho do Homem seja levantado,"},
{v:15,t:"para que todo o que crê tenha nele a vida eterna."},
{v:16,t:"Pois Deus amou tanto o mundo, que deu o seu Filho unigênito, para que todo o que crê nele não pereça, mas tenha a vida eterna."},
{v:17,t:"Porque Deus não enviou o seu Filho ao mundo para julgar o mundo, mas para que o mundo seja salvo por ele."},
{v:18,t:"Quem crê nele não é julgado; quem não crê já está julgado, porque não creu no nome do Filho unigênito de Deus."},
{v:19,t:"O julgamento é este: a luz veio ao mundo, e os homens amaram mais as trevas do que a luz, porque as suas obras eram más."},
{v:20,t:"Pois todo o que pratica o mal odeia a luz e não vem para a luz, para que as suas obras não sejam reprovadas;"},
{v:21,t:"mas quem pratica a verdade vem para a luz, para que se manifeste que as suas obras são feitas em Deus."}
];

EV[26] = [
{p:"João 3:22-36"},
{v:22,t:"Depois disso, Jesus foi com os seus discípulos para a terra da Judeia; permanecia ali com eles e batizava."},
{v:23,t:"João também batizava em Enon, perto de Salim, porque havia ali muitas águas, e as pessoas iam e eram batizadas;"},
{v:24,t:"pois João ainda não tinha sido lançado na prisão."},
{v:25,t:"Surgiu então uma discussão entre os discípulos de João e um judeu, a respeito da purificação."},
{v:26,t:"Foram a João e disseram: Rabi, aquele que estava contigo além do Jordão, de quem deste testemunho, ei-lo batizando, e todos vão a ele."},
{v:27,t:"João respondeu: Ninguém pode receber coisa alguma, se não for dada a ele do céu."},
{v:28,t:"Vós mesmos sois testemunhas de que eu disse: Eu não sou o Cristo, mas fui enviado adiante dele."},
{v:29,t:"Quem tem a esposa é o esposo; mas o amigo do esposo, que está presente e o ouve, alegra-se muito com a voz do esposo. Esta minha alegria está completa."},
{v:30,t:"É necessário que ele cresça e que eu diminua."},
{v:31,t:"Quem vem do alto está acima de todos; quem é da terra pertence à terra e fala da terra. Quem vem do céu está acima de todos:"},
{v:32,t:"dá testemunho do que viu e ouviu, e ninguém recebe o seu testemunho."},
{v:33,t:"Quem recebe o seu testemunho atesta que Deus é verdadeiro."},
{v:34,t:"Pois aquele que Deus enviou fala as palavras de Deus, porque ele dá o Espírito sem medida."},
{v:35,t:"O Pai ama o Filho e entregou tudo na sua mão."},
{v:36,t:"Quem crê no Filho tem a vida eterna; quem não obedece ao Filho não verá a vida, mas a ira de Deus permanece sobre ele."}
];

EV[27] = [
{p:"João 4:1-42"},
{v:1,t:"Quando Jesus soube que os fariseus tinham ouvido dizer que ele fazia mais discípulos e batizava mais do que João"},
{v:2,t:"— embora Jesus mesmo não batizasse, mas os seus discípulos —,"},
{v:3,t:"deixou a Judeia e partiu de novo para a Galileia."},
{v:4,t:"Devia passar pela Samaria."},
{v:5,t:"Chegou então a uma cidade da Samaria chamada Sicar, perto do terreno que Jacó dera a seu filho José."},
{v:6,t:"Ficava ali o poço de Jacó. Jesus, cansado da caminhada, sentou-se junto ao poço; era por volta da hora sexta.",n:"Por volta do meio-dia."},
{v:7,t:"Veio uma mulher da Samaria tirar água. Jesus disse a ela: Dá-me de beber."},
{v:8,t:"Os seus discípulos tinham ido à cidade comprar alimento."},
{v:9,t:"A mulher samaritana disse a ele: Como tu, sendo judeu, pedes de beber a mim, que sou samaritana? Pois os judeus não se dão com os samaritanos."},
{v:10,t:"Jesus respondeu: Se conhecesses o dom de Deus e quem é o que te diz: Dá-me de beber, tu é que pedirias a ele, e ele daria a ti água viva.",n:"Água viva designa, no uso comum, a água corrente de fonte; nos lábios de Jesus, o dom do Espírito."},
{v:11,t:"A mulher disse: Senhor, não tens com que tirar a água, e o poço é fundo; donde tens, pois, a água viva?"},
{v:12,t:"És maior do que o nosso pai Jacó, que nos deu o poço e dele bebeu, com os seus filhos e o seu gado?"},
{v:13,t:"Jesus respondeu: Todo o que bebe desta água terá sede de novo,"},
{v:14,t:"mas quem beber da água que eu darei a ele nunca mais terá sede: a água que eu darei se tornará nele uma fonte de água que jorra para a vida eterna."},
{v:15,t:"A mulher disse: Senhor, dá-me dessa água, para que eu não tenha mais sede nem venha aqui tirá-la."},
{v:16,t:"Ele disse: Vai, chama o teu marido e volta aqui."},
{v:17,t:"A mulher respondeu: Não tenho marido. Jesus disse: Disseste bem: não tenho marido;"},
{v:18,t:"pois tiveste cinco maridos, e o que agora tens não é teu marido; nisso falaste a verdade."},
{v:19,t:"A mulher disse: Senhor, vejo que és profeta."},
{v:20,t:"Os nossos pais adoraram neste monte, e vós dizeis que em Jerusalém está o lugar onde se deve adorar.",n:"O monte é o Garizim, onde os samaritanos tinham erguido o seu templo."},
{v:21,t:"Jesus disse: Mulher, crê em mim: vem a hora em que nem neste monte nem em Jerusalém adorareis o Pai."},
{v:22,t:"Vós adorais o que não conheceis; nós adoramos o que conhecemos, porque a salvação vem dos judeus."},
{v:23,t:"Mas vem a hora, e é agora, em que os verdadeiros adoradores adorarão o Pai em espírito e verdade, pois são esses os adoradores que o Pai procura."},
{v:24,t:"Deus é espírito, e os que o adoram devem adorar em espírito e verdade."},
{v:25,t:"A mulher disse: Sei que vem o Messias, chamado Cristo; quando ele vier, anunciará a nós todas as coisas."},
{v:26,t:"Jesus disse a ela: Sou eu, que falo contigo."},
{v:27,t:"Nisso chegaram os seus discípulos e admiravam-se de que falasse com uma mulher; contudo, ninguém perguntou: Que procuras? ou: Por que falas com ela?"},
{v:28,t:"A mulher deixou o seu cântaro, foi à cidade e disse às pessoas:"},
{v:29,t:"Vinde ver um homem que me disse tudo o que fiz. Não será ele o Cristo?"},
{v:30,t:"Saíram da cidade e foram ao seu encontro."},
{v:31,t:"Entretanto, os discípulos pediam a ele: Rabi, come."},
{v:32,t:"Mas ele disse: Eu tenho um alimento para comer que vós não conheceis."},
{v:33,t:"Os discípulos diziam entre si: Alguém trouxe de comer para ele?"},
{v:34,t:"Jesus disse a eles: O meu alimento é fazer a vontade daquele que me enviou e consumar a sua obra."},
{v:35,t:"Não dizeis vós que ainda faltam quatro meses para a colheita? Eis que eu vos digo: levantai os olhos e vede os campos, que já estão dourados para a colheita."},
{v:36,t:"O que colhe recebe salário e recolhe fruto para a vida eterna, para que se alegrem juntos o que semeia e o que colhe."},
{v:37,t:"Nisto é verdadeiro o provérbio: um é o que semeia, outro o que colhe."},
{v:38,t:"Eu vos enviei a colher o que não trabalhastes; outros trabalharam, e vós entrastes no seu trabalho."},
{v:39,t:"Muitos samaritanos daquela cidade creram nele por causa da palavra da mulher, que testemunhava: Ele me disse tudo o que fiz."},
{v:40,t:"Por isso, quando os samaritanos foram ao seu encontro, pediram a ele que permanecesse com eles; e permaneceu ali dois dias."},
{v:41,t:"E muitos mais creram por causa da sua palavra"},
{v:42,t:"e diziam à mulher: Já não é por causa do que disseste que cremos; nós mesmos ouvimos e sabemos que este é verdadeiramente o Salvador do mundo."}
];

EV[28] = [
{p:"João 4:43-54"},
{v:43,t:"Passados os dois dias, partiu dali para a Galileia."},
{v:44,t:"O próprio Jesus testemunhara que um profeta não tem honra na sua pátria."},
{v:45,t:"Quando chegou à Galileia, os galileus o acolheram, porque tinham visto tudo o que fizera em Jerusalém durante a festa; pois também eles tinham ido à festa."},
{v:46,t:"Foi então de novo a Caná da Galileia, onde transformara a água em vinho. Havia um funcionário real cujo filho estava doente em Cafarnaum."},
{v:47,t:"Ao ouvir que Jesus chegara da Judeia à Galileia, foi ao seu encontro e pedia a ele que descesse e curasse o seu filho, que estava à morte."},
{v:48,t:"Jesus disse a ele: Se não virdes sinais e prodígios, não credes."},
{v:49,t:"O funcionário disse: Senhor, desce, antes que o meu menino morra."},
{v:50,t:"Jesus respondeu: Vai, o teu filho vive. O homem creu na palavra que Jesus dissera a ele e partiu."},
{v:51,t:"Quando já descia, os seus servos vieram ao seu encontro, dizendo que o seu menino vivia."},
{v:52,t:"Perguntou a eles a hora em que melhorara; responderam: Ontem, à hora sétima, a febre o deixou.",n:"Cerca de uma hora da tarde."},
{v:53,t:"O pai reconheceu que era aquela a hora em que Jesus dissera: O teu filho vive; e creu ele e toda a sua casa."},
{v:54,t:"Este segundo sinal fez Jesus, ao voltar da Judeia para a Galileia."}
];

EV[29] = [
{p:"Mateus 14:3-5"},
{v:3,t:"Pois Herodes prendera João, acorrentara-o e o metera no cárcere por causa de Herodíades, mulher de Filipe, seu irmão,"},
{v:4,t:"porque João dizia a ele: Não é lícito a ti possuí-la."},
{v:5,t:"E, querendo matá-lo, temia o povo, porque o tinham por profeta."},
{p:"Lucas 3:19-20"},
{v:19,t:"Mas Herodes, o tetrarca, repreendido por ele por causa de Herodíades, mulher do seu irmão, e por todos os males que praticara,"},
{v:20,t:"acrescentou a todos eles ainda este: encerrou João no cárcere."}
];

EV[30] = [
{p:"João 5:1-15"},
{v:1,t:"Depois disso, havia uma festa dos judeus, e Jesus subiu a Jerusalém."},
{v:2,t:"Há em Jerusalém, junto à porta das Ovelhas, uma piscina chamada em hebraico Betesda, que tem cinco pórticos."},
{v:3,t:"Neles jazia uma multidão de enfermos: cegos, coxos, paralíticos.",n:"A parte final do v. 3 e o v. 4, sobre o anjo que descia a agitar a água, faltam nos manuscritos mais antigos; a Nova Vulgata os omite, e a numeração salta do v. 3 ao v. 5."},
{v:5,t:"Estava ali um homem enfermo havia trinta e oito anos."},
{v:6,t:"Jesus, vendo-o deitado e sabendo que estava assim havia muito tempo, disse a ele: Queres ficar são?"},
{v:7,t:"O enfermo respondeu: Senhor, não tenho ninguém que me ponha na piscina quando a água é agitada; enquanto eu vou, outro desce antes de mim."},
{v:8,t:"Jesus disse a ele: Levanta-te, toma o teu leito e anda."},
{v:9,t:"No mesmo instante, o homem ficou são, tomou o seu leito e andava. Aquele dia era sábado."},
{v:10,t:"Os judeus diziam então ao que fora curado: É sábado; não é lícito a ti carregar o teu leito."},
{v:11,t:"Ele respondeu: Aquele que me fez são disse a mim: Toma o teu leito e anda."},
{v:12,t:"Perguntaram: Quem é o homem que te disse: Toma e anda?"},
{v:13,t:"Mas o que fora curado não sabia quem era, pois Jesus se afastara da multidão que estava naquele lugar."},
{v:14,t:"Depois disso, Jesus o encontrou no Templo e disse a ele: Eis que ficaste são; não peques mais, para que não te aconteça coisa pior."},
{v:15,t:"O homem foi anunciar aos judeus que fora Jesus quem o fizera são."}
];

EV[31] = [
{p:"João 5:16-47"},
{v:16,t:"Por isso os judeus perseguiam Jesus, porque fazia essas coisas no sábado."},
{v:17,t:"Mas ele respondeu a eles: Meu Pai trabalha até agora, e eu também trabalho.",n:"O descanso do sétimo dia não interrompe a obra pela qual Deus conserva o mundo; ao dizer que trabalha com o Pai, Jesus reivindica a mesma obra, e é isso que os ouvintes entendem no versículo seguinte."},
{v:18,t:"Por isso os judeus procuravam ainda mais matá-lo, porque não só violava o sábado, mas também dizia que Deus era seu próprio Pai, fazendo-se igual a Deus."},
{v:19,t:"Jesus respondeu e disse a eles: Em verdade, em verdade vos digo: o Filho não pode fazer nada de si mesmo, senão o que vê o Pai fazer; pois o que este faz, o Filho o faz igualmente."},
{v:20,t:"Porque o Pai ama o Filho e mostra a ele tudo o que faz; e obras maiores do que estas mostrará a ele, para que vos admireis."},
{v:21,t:"Pois, como o Pai ressuscita os mortos e lhes dá a vida, assim também o Filho dá a vida a quem quer."},
{v:22,t:"Porque o Pai não julga ninguém, mas entregou todo o julgamento ao Filho,"},
{v:23,t:"para que todos honrem o Filho como honram o Pai. Quem não honra o Filho não honra o Pai que o enviou."},
{v:24,t:"Em verdade, em verdade vos digo: quem ouve a minha palavra e crê naquele que me enviou tem a vida eterna e não vem a julgamento, mas passou da morte para a vida."},
{v:25,t:"Em verdade, em verdade vos digo: vem a hora, e é agora, em que os mortos ouvirão a voz do Filho de Deus, e os que a ouvirem viverão.",n:"E é agora: a ressurreição final já começou a agir no presente, nos que passam da morte do pecado para a vida pela fé. Nos vv. 28-29 o mesmo anúncio se volta para a ressurreição dos corpos."},
{v:26,t:"Pois, como o Pai tem a vida em si mesmo, assim também deu ao Filho ter a vida em si mesmo;"},
{v:27,t:"e deu a ele o poder de exercer o julgamento, porque é Filho do Homem.",n:"Aqui a expressão vem sem artigo em grego, aproximando-se da visão de Daniel 7, em que um como filho de homem recebe o poder de julgar."},
{v:28,t:"Não vos admireis disso, porque vem a hora em que todos os que estão nos sepulcros ouvirão a sua voz"},
{v:29,t:"e sairão: os que fizeram o bem, para a ressurreição da vida; os que praticaram o mal, para a ressurreição do julgamento."},
{v:30,t:"Eu não posso fazer nada de mim mesmo. Julgo conforme ouço, e o meu julgamento é justo, porque não busco a minha vontade, mas a vontade daquele que me enviou."},
{v:31,t:"Se eu dou testemunho de mim mesmo, o meu testemunho não é válido.",n:"A Lei não aceitava a palavra de uma só testemunha; Jesus assume a exigência e passa a enumerar as testemunhas que o abonam: João, as obras, o Pai, as Escrituras."},
{v:32,t:"Outro é o que dá testemunho de mim, e sei que é verdadeiro o testemunho que ele dá de mim."},
{v:33,t:"Vós enviastes mensageiros a João, e ele deu testemunho da verdade."},
{v:34,t:"Eu, porém, não recebo testemunho de homem; digo isso para que sejais salvos."},
{v:35,t:"Ele era a lâmpada que arde e ilumina, e vós quisestes alegrar-vos por um momento na sua luz."},
{v:36,t:"Mas eu tenho um testemunho maior que o de João: as obras que o Pai me deu para realizar, essas mesmas obras que faço dão testemunho de mim, de que o Pai me enviou."},
{v:37,t:"E o Pai que me enviou, ele mesmo deu testemunho de mim. Nunca ouvistes a sua voz, nem vistes a sua face,"},
{v:38,t:"e não tendes a sua palavra permanecendo em vós, porque não credes naquele que ele enviou."},
{v:39,t:"Examinais as Escrituras, porque julgais ter nelas a vida eterna; e são elas que dão testemunho de mim.",n:"A forma grega tanto pode ser afirmação como ordem: examinais as Escrituras ou examinai as Escrituras. O sentido não muda muito, pois a censura recai sobre parar no livro sem chegar àquele de quem o livro fala."},
{v:40,t:"E não quereis vir a mim para terdes a vida."},
{v:41,t:"Não recebo glória dos homens."},
{v:42,t:"Mas eu vos conheço: não tendes em vós o amor de Deus."},
{v:43,t:"Eu vim em nome de meu Pai, e não me recebeis; se outro vier em seu próprio nome, a esse recebereis."},
{v:44,t:"Como podeis crer, vós que recebeis glória uns dos outros e não buscais a glória que vem do Deus único?"},
{v:45,t:"Não penseis que eu vos acusarei diante do Pai; há quem vos acuse: Moisés, em quem esperais."},
{v:46,t:"Pois, se crêsseis em Moisés, creríeis também em mim, porque ele escreveu a meu respeito."},
{v:47,t:"Mas, se não credes nos seus escritos, como crereis nas minhas palavras?"}
];

EV[32] = [
{p:"Mateus 4:12"},
{v:12,t:"Ouvindo que João fora entregue, retirou-se para a Galileia.",n:"Entregue verte paradothenai, o mesmo verbo que os Evangelhos usarão para a entrega de Jesus: a sorte do precursor prefigura a do Senhor."},
{p:"Marcos 1:14-15"},
{v:14,t:"Depois que João foi entregue, Jesus foi para a Galileia, pregando o Evangelho de Deus"},
{v:15,t:"e dizendo: O tempo está cumprido e o Reino de Deus está próximo; convertei-vos e crede no Evangelho.",n:"Convertei-vos traduz metanoeite, que pede uma mudança do modo de pensar e de julgar, e não apenas o pesar pelo que se fez."},
{p:"Lucas 4:14-15"},
{v:14,t:"E Jesus voltou, no poder do Espírito, para a Galileia, e a sua fama correu por toda a região vizinha."},
{v:15,t:"Ele ensinava nas suas sinagogas, glorificado por todos."}
];

EV[33] = [
{p:"Lucas 4:16-30"},
{v:16,t:"Foi a Nazaré, onde fora criado, e entrou, segundo o seu costume, no dia de sábado, na sinagoga, e levantou-se para ler."},
{v:17,t:"Foi dado a ele o livro do profeta Isaías; e, desenrolando o livro, encontrou o lugar onde estava escrito:"},
{v:18,t:"O Espírito do Senhor está sobre mim, pelo que me ungiu para anunciar a Boa Nova aos pobres; enviou-me a proclamar aos cativos a libertação e aos cegos a recuperação da vista, a pôr em liberdade os oprimidos,",n:"Ungiu verte echrisen, do mesmo radical de Cristo: ao ler Isaías, Jesus diz que a unção anunciada recai sobre ele."},
{v:19,t:"a proclamar um ano de graça do Senhor.",n:"O ano de graça é o jubileu de Levítico 25, em que se perdoavam as dívidas e se devolviam as terras; Jesus o toma como figura do que vem realizar."},
{v:20,t:"Enrolando o livro, devolveu-o ao servente e sentou-se; e os olhos de todos na sinagoga estavam fixos nele."},
{v:21,t:"Começou a dizer a eles: Hoje se cumpriu esta Escritura aos vossos ouvidos."},
{v:22,t:"E todos davam testemunho dele e admiravam-se das palavras de graça que saíam da sua boca, e diziam: Não é este o filho de José?"},
{v:23,t:"Ele disse a eles: Sem dúvida me direis este provérbio: Médico, cura-te a ti mesmo. Tudo o que ouvimos ter acontecido em Cafarnaum, faze-o também aqui, na tua pátria."},
{v:24,t:"E acrescentou: Em verdade vos digo que nenhum profeta é bem recebido na sua pátria."},
{v:25,t:"Na verdade vos digo: muitas viúvas havia em Israel nos dias de Elias, quando o céu se fechou por três anos e seis meses, de modo que houve grande fome por toda a terra;"},
{v:26,t:"e a nenhuma delas foi enviado Elias, senão a uma mulher viúva de Sarepta, na Sidônia."},
{v:27,t:"E muitos leprosos havia em Israel no tempo do profeta Eliseu; e nenhum deles foi purificado, senão Naamã, o sírio.",n:"Os dois exemplos são de estrangeiros socorridos enquanto Israel era passado adiante; é essa universalidade, e não a pretensão messiânica, o que acende a ira dos ouvintes."},
{v:28,t:"Ouvindo isso, todos na sinagoga se encheram de ira;"},
{v:29,t:"e, levantando-se, lançaram-no fora da cidade e o levaram até ao alto do monte sobre o qual a sua cidade estava edificada, para o precipitarem."},
{v:30,t:"Ele, porém, passando pelo meio deles, seguia o seu caminho."}
];

EV[34] = [
{p:"Mateus 4:13-17"},
{v:13,t:"E, deixando Nazaré, foi habitar em Cafarnaum, à beira-mar, nos confins de Zabulon e Neftali,"},
{v:14,t:"para que se cumprisse o que foi dito pelo profeta Isaías:"},
{v:15,t:"Terra de Zabulon e terra de Neftali, caminho do mar, além do Jordão, Galileia dos gentios:"},
{v:16,t:"o povo que jazia nas trevas viu uma grande luz; e sobre os que jaziam na região e sombra da morte, uma luz se levantou."},
{v:17,t:"Desde então começou Jesus a pregar e a dizer: Convertei-vos, porque o Reino dos céus está próximo.",n:"Reino dos céus é a forma preferida por São Mateus, que evita pronunciar o nome de Deus; equivale ao Reino de Deus dos outros evangelistas."},
{p:"Lucas 4:31"},
{v:31,t:"Desceu a Cafarnaum, cidade da Galileia, e ali os ensinava nos sábados."}
];

EV[35] = [
{p:"Mateus 4:18-22"},
{v:18,t:"Caminhando junto ao mar da Galileia, viu dois irmãos, Simão, chamado Pedro, e André, seu irmão, lançando a rede ao mar, pois eram pescadores."},
{v:19,t:"E disse a eles: Vinde após mim, e eu vos farei pescadores de homens."},
{v:20,t:"Eles, deixando imediatamente as redes, seguiram-no."},
{v:21,t:"Passando adiante, viu outros dois irmãos, Tiago, filho de Zebedeu, e João, seu irmão, na barca com Zebedeu, seu pai, consertando as suas redes; e os chamou."},
{v:22,t:"Eles, deixando imediatamente a barca e seu pai, seguiram-no."},
{p:"Marcos 1:16-20"},
{v:16,t:"Passando junto ao mar da Galileia, viu Simão e André, irmão de Simão, lançando as redes ao mar, pois eram pescadores."},
{v:17,t:"E disse a eles Jesus: Vinde após mim, e farei que vos torneis pescadores de homens."},
{v:18,t:"E logo, deixando as redes, seguiram-no."},
{v:19,t:"Adiantando-se um pouco, viu Tiago, filho de Zebedeu, e João, seu irmão, também eles na barca, consertando as redes;"},
{v:20,t:"e logo os chamou. Deixando na barca seu pai Zebedeu com os assalariados, foram após ele."},
{p:"Lucas 5:1-11"},
{v:1,t:"Ora, apertando-o a multidão para ouvir a palavra de Deus, ele estava junto ao lago de Genesaré,"},
{v:2,t:"e viu duas barcas paradas à beira do lago; os pescadores tinham descido delas e lavavam as redes."},
{v:3,t:"Subindo a uma das barcas, que era de Simão, pediu a ele que se afastasse um pouco da terra; e, sentado, ensinava as multidões desde a barca."},
{v:4,t:"Quando acabou de falar, disse a Simão: Faze-te ao largo e lançai as vossas redes para a pesca.",n:"A ordem passa do singular ao plural: faze-te tu ao largo, lançai vós as redes. O gesto é de Pedro, mas o trabalho é de todos."},
{v:5,t:"Simão respondeu: Mestre, trabalhamos a noite toda e nada apanhamos; mas, sobre a tua palavra, lançarei as redes."},
{v:6,t:"Feito isso, apanharam grande quantidade de peixes, e as suas redes rompiam-se."},
{v:7,t:"Fizeram sinal aos companheiros da outra barca, para que viessem ajudá-los; e vieram, e encheram ambas as barcas, a ponto de quase se afundarem."},
{v:8,t:"Vendo isso, Simão Pedro caiu aos joelhos de Jesus, dizendo: Afasta-te de mim, Senhor, porque sou um homem pecador."},
{v:9,t:"Pois o espanto o tomara, e a todos os que estavam com ele, pela pesca que tinham feito;"},
{v:10,t:"e igualmente a Tiago e a João, filhos de Zebedeu, que eram companheiros de Simão. E Jesus disse a Simão: Não temas; de agora em diante serás pescador de homens.",n:"O verbo grego zogrein significa apanhar vivo, poupar da morte; a pesca de que se fala não tira a vida, dá-a."},
{v:11,t:"E, levando as barcas para a terra, deixaram tudo e seguiram-no."}
];

EV[36] = [
{p:"Marcos 1:21-28"},
{v:21,t:"Entraram em Cafarnaum; e logo, no sábado, entrando na sinagoga, ensinava."},
{v:22,t:"E admiravam-se do seu ensino, porque os ensinava como quem tem autoridade, e não como os escribas.",n:"Os escribas ensinavam apoiando-se na cadeia dos mestres antigos; Jesus fala por si, e é essa exousia, autoridade que não se recebeu de outro, o que espanta."},
{v:23,t:"Havia logo na sinagoga deles um homem com espírito impuro, e ele gritou:"},
{v:24,t:"Que temos nós contigo, Jesus Nazareno? Vieste perder-nos? Sei quem tu és: o Santo de Deus.",n:"Que temos nós contigo traduz ao pé da letra um modo de dizer hebraico que recusa qualquer trato: não te metas conosco."},
{v:25,t:"Jesus o repreendeu, dizendo: Cala-te e sai dele."},
{v:26,t:"E o espírito impuro, agitando-o com violência e gritando com grande voz, saiu dele."},
{v:27,t:"Todos ficaram tão espantados que perguntavam entre si: Que é isto? Um ensino novo, com autoridade! Ele manda até nos espíritos impuros, e obedecem a ele."},
{v:28,t:"E logo a sua fama se espalhou por toda parte, em toda a região da Galileia."},
{p:"Lucas 4:32-37"},
{v:32,t:"E admiravam-se do seu ensino, porque a sua palavra era com autoridade."},
{v:33,t:"Havia na sinagoga um homem que tinha um espírito de demônio impuro, e gritou com grande voz:"},
{v:34,t:"Ah! Que temos nós contigo, Jesus Nazareno? Vieste perder-nos? Sei quem tu és: o Santo de Deus."},
{v:35,t:"Jesus o repreendeu, dizendo: Cala-te e sai dele. E o demônio, lançando-o por terra no meio, saiu dele sem lhe fazer mal algum."},
{v:36,t:"O espanto tomou a todos, e diziam uns aos outros: Que palavra é esta, que com autoridade e poder manda nos espíritos impuros, e eles saem?"},
{v:37,t:"E a sua fama se difundia por todos os lugares da região."}
];

EV[37] = [
{p:"Mateus 8:14-17"},
{v:14,t:"Chegando Jesus à casa de Pedro, viu a sogra dele deitada e com febre."},
{v:15,t:"Tocou-lhe a mão, e a febre a deixou; ela se levantou e o servia."},
{v:16,t:"Caída a tarde, trouxeram a ele muitos endemoninhados; e ele expulsava os espíritos com uma palavra, e curou todos os que estavam mal,"},
{v:17,t:"para que se cumprisse o que foi dito pelo profeta Isaías: Ele tomou as nossas enfermidades e carregou as nossas doenças."},
{p:"Marcos 1:29-34"},
{v:29,t:"E logo, saindo da sinagoga, foram à casa de Simão e André, com Tiago e João."},
{v:30,t:"A sogra de Simão estava de cama, com febre; e logo falaram a ele dela."},
{v:31,t:"Aproximando-se, ele a levantou, tomando-a pela mão; a febre a deixou, e ela os servia."},
{v:32,t:"Caída a tarde, quando o sol se pôs, traziam a ele todos os que estavam mal e os endemoninhados;",n:"Esperam o pôr do sol porque com ele acaba o sábado e volta a ser lícito carregar os doentes."},
{v:33,t:"e a cidade inteira estava reunida à porta."},
{v:34,t:"Curou muitos que estavam mal de diversas doenças e expulsou muitos demônios; e não deixava falar os demônios, porque o conheciam."},
{p:"Lucas 4:38-41"},
{v:38,t:"Levantando-se da sinagoga, entrou na casa de Simão. A sogra de Simão estava tomada de grande febre, e rogaram a ele por ela."},
{v:39,t:"Inclinando-se sobre ela, repreendeu a febre, e a febre a deixou; e ela, levantando-se imediatamente, os servia."},
{v:40,t:"Ao pôr do sol, todos os que tinham enfermos de várias doenças os traziam a ele; e ele, impondo as mãos sobre cada um, os curava."},
{v:41,t:"Também saíam demônios de muitos, gritando: Tu és o Filho de Deus. Mas ele os repreendia e não os deixava falar, porque sabiam que ele era o Cristo."}
];

EV[38] = [
{p:"Mateus 4:23-25"},
{v:23,t:"E percorria toda a Galileia, ensinando nas suas sinagogas, pregando o Evangelho do Reino e curando toda doença e toda enfermidade no povo."},
{v:24,t:"A sua fama correu por toda a Síria; e traziam a ele todos os que estavam mal, atormentados por várias doenças e sofrimentos, endemoninhados, lunáticos e paralíticos; e ele os curou."},
{v:25,t:"E seguiram-no numerosas multidões da Galileia, da Decápole, de Jerusalém, da Judeia e de além do Jordão."},
{p:"Marcos 1:35-39"},
{v:35,t:"De madrugada, ainda muito escuro, levantou-se, saiu e foi a um lugar deserto, e ali orava."},
{v:36,t:"Simão e os que estavam com ele foram à sua procura;"},
{v:37,t:"e, encontrando-o, disseram a ele: Todos te buscam."},
{v:38,t:"Ele respondeu: Vamos a outra parte, às povoações vizinhas, para que também ali eu pregue; pois para isso saí."},
{v:39,t:"E foi pregar nas sinagogas deles, por toda a Galileia, e expulsava os demônios."},
{p:"Lucas 4:42-44"},
{v:42,t:"Sendo já dia, saiu e foi a um lugar deserto; as multidões o procuravam e chegaram até ele, e o retinham, para que não se afastasse delas."},
{v:43,t:"Ele disse a eles: É necessário que eu anuncie o Reino de Deus também às outras cidades, pois para isso fui enviado."},
{v:44,t:"E pregava nas sinagogas da Judeia.",n:"Judeia está aqui no sentido largo de terra dos judeus, abrangendo a Galileia; parte dos manuscritos traz justamente Galileia."}
];

EV[39] = [
{p:"Mateus 8:1-4"},
{v:1,t:"Quando desceu do monte, seguiram-no numerosas multidões."},
{v:2,t:"E eis que um leproso, aproximando-se, prostrava-se diante dele, dizendo: Senhor, se queres, podes purificar-me."},
{v:3,t:"Estendendo a mão, ele o tocou, dizendo: Quero, sê purificado. E logo a sua lepra foi purificada.",n:"Tocar um leproso tornava impuro quem o tocasse; aqui dá-se o contrário, e é a impureza que cede ao contato."},
{v:4,t:"Jesus disse a ele: Olha, não digas a ninguém; mas vai, mostra-te ao sacerdote e apresenta a oferta que Moisés ordenou, em testemunho para eles."},
{p:"Marcos 1:40-45"},
{v:40,t:"Veio a ele um leproso, suplicando e pondo-se de joelhos, e disse: Se queres, podes purificar-me."},
{v:41,t:"Compadecido, estendeu a mão, tocou-o e disse: Quero, sê purificado.",n:"Alguns manuscritos antigos trazem irado em lugar de compadecido; a lição mais difícil apontaria para a cólera de Jesus diante do mal que desfigura o homem."},
{v:42,t:"E logo a lepra o deixou, e ficou purificado."},
{v:43,t:"Ele o despediu imediatamente, advertindo-o com severidade,"},
{v:44,t:"e disse a ele: Vê, não digas nada a ninguém; mas vai, mostra-te ao sacerdote e oferece pela tua purificação o que Moisés ordenou, em testemunho para eles."},
{v:45,t:"Mas ele, saindo, começou a apregoar muito e a divulgar o acontecido, de modo que Jesus já não podia entrar publicamente numa cidade, mas ficava fora, em lugares desertos; e vinham a ele de toda parte."},
{p:"Lucas 5:12-16"},
{v:12,t:"Estando ele numa das cidades, eis um homem cheio de lepra; vendo Jesus, caiu de rosto por terra e rogou a ele: Senhor, se queres, podes purificar-me."},
{v:13,t:"Estendendo a mão, tocou-o, dizendo: Quero, sê purificado. E logo a lepra o deixou."},
{v:14,t:"E ele lhe ordenou que não dissesse a ninguém: Mas vai, mostra-te ao sacerdote e oferece pela tua purificação o que Moisés ordenou, em testemunho para eles."},
{v:15,t:"A sua fama, porém, se difundia ainda mais, e grandes multidões acorriam para o ouvir e para serem curadas das suas enfermidades."},
{v:16,t:"Ele, porém, retirava-se para lugares desertos e orava."}
];

EV[40] = [
{p:"Mateus 9:2-8"},
{v:2,t:"E eis que traziam a ele um paralítico, deitado num leito. Vendo Jesus a fé deles, disse ao paralítico: Confia, filho; os teus pecados são perdoados.",n:"A fé deles é a dos que carregam o doente: em toda a cena, quem crê são os amigos, e é a essa fé que o perdão responde."},
{v:3,t:"E eis que alguns escribas disseram entre si: Este blasfema."},
{v:4,t:"Vendo Jesus os pensamentos deles, disse: Por que pensais o mal nos vossos corações?"},
{v:5,t:"Que é mais fácil dizer: Os teus pecados são perdoados; ou dizer: Levanta-te e anda?"},
{v:6,t:"Ora, para que saibais que o Filho do Homem tem sobre a terra o poder de perdoar pecados — disse então ao paralítico: Levanta-te, toma o teu leito e vai para tua casa.",n:"A frase fica suspensa: Jesus interrompe o que dizia aos escribas para se voltar ao doente, e a cura termina o que a palavra começara."},
{v:7,t:"E ele, levantando-se, foi para sua casa."},
{v:8,t:"Vendo isso, as multidões temeram e glorificaram a Deus, que deu tal poder aos homens."},
{p:"Marcos 2:1-12"},
{v:1,t:"Entrou de novo em Cafarnaum, passados alguns dias, e ouviu-se que estava em casa."},
{v:2,t:"Reuniram-se muitos, de modo que já não havia lugar nem junto à porta; e ele lhes anunciava a palavra."},
{v:3,t:"Vieram, trazendo a ele um paralítico, carregado por quatro."},
{v:4,t:"E, não podendo apresentá-lo diante dele por causa da multidão, descobriram o teto onde ele estava e, abrindo uma passagem, baixaram o leito em que jazia o paralítico."},
{v:5,t:"Vendo Jesus a fé deles, disse ao paralítico: Filho, os teus pecados são perdoados."},
{v:6,t:"Estavam ali sentados alguns escribas, que pensavam nos seus corações:"},
{v:7,t:"Por que este fala assim? Ele blasfema. Quem pode perdoar pecados, senão um só, que é Deus?"},
{v:8,t:"Conhecendo logo Jesus, no seu espírito, que assim pensavam entre si, disse a eles: Por que pensais essas coisas nos vossos corações?"},
{v:9,t:"Que é mais fácil dizer ao paralítico: Os teus pecados são perdoados; ou dizer: Levanta-te, toma o teu leito e anda?"},
{v:10,t:"Ora, para que saibais que o Filho do Homem tem sobre a terra o poder de perdoar pecados — disse ao paralítico:"},
{v:11,t:"A ti eu digo: Levanta-te, toma o teu leito e vai para tua casa."},
{v:12,t:"E ele se levantou e, tomando logo o leito, saiu à vista de todos, de modo que todos se admiravam e glorificavam a Deus, dizendo: Nunca vimos coisa assim."},
{p:"Lucas 5:17-26"},
{v:17,t:"Num dos dias, estava ele ensinando; e estavam sentados fariseus e doutores da Lei, vindos de todas as aldeias da Galileia, da Judeia e de Jerusalém; e o poder do Senhor estava com ele para curar."},
{v:18,t:"E eis uns homens que traziam num leito um homem paralítico, e procuravam introduzi-lo e pô-lo diante dele."},
{v:19,t:"Não achando por onde introduzi-lo, por causa da multidão, subiram ao terraço e, pelas telhas, baixaram-no com o leito para o meio, diante de Jesus."},
{v:20,t:"Vendo ele a fé deles, disse: Homem, os teus pecados são perdoados."},
{v:21,t:"Os escribas e fariseus começaram a pensar: Quem é este, que fala blasfêmias? Quem pode perdoar pecados, senão só Deus?"},
{v:22,t:"Conhecendo Jesus os pensamentos deles, respondeu: Que pensais nos vossos corações?"},
{v:23,t:"Que é mais fácil dizer: Os teus pecados são perdoados; ou dizer: Levanta-te e anda?"},
{v:24,t:"Ora, para que saibais que o Filho do Homem tem sobre a terra o poder de perdoar pecados — disse ao paralítico: A ti eu digo: Levanta-te, toma o teu leito e vai para tua casa."},
{v:25,t:"E logo, levantando-se diante deles, tomou o leito em que jazia e foi para sua casa, glorificando a Deus."},
{v:26,t:"O assombro tomou a todos, e glorificavam a Deus; e, cheios de temor, diziam: Vimos hoje coisas admiráveis."}
];

EV[41] = [
{p:"Mateus 9:9"},
{v:9,t:"Passando dali, Jesus viu um homem sentado na coletoria, chamado Mateus, e disse a ele: Segue-me. Ele se levantou e o seguiu.",n:"O mesmo homem é chamado Levi por São Marcos e São Lucas; a tradição vê nos dois nomes uma só pessoa, o publicano que se tornou evangelista."},
{p:"Marcos 2:13-14"},
{v:13,t:"Saiu de novo para a beira-mar; toda a multidão vinha a ele, e ele os ensinava."},
{v:14,t:"Ao passar, viu Levi, filho de Alfeu, sentado na coletoria, e disse a ele: Segue-me. Ele se levantou e o seguiu."},
{p:"Lucas 5:27-28"},
{v:27,t:"Depois disso, saiu e viu um publicano chamado Levi, sentado na coletoria, e disse a ele: Segue-me."},
{v:28,t:"Ele, deixando tudo, levantou-se e o seguiu."}
];

EV[42] = [
{p:"Mateus 12:1-8"},
{v:1,t:"Naquele tempo, Jesus passou pelas searas no sábado; os seus discípulos, tendo fome, começaram a arrancar espigas e a comer."},
{v:2,t:"Vendo isso, os fariseus disseram a ele: Eis que os teus discípulos fazem o que não é lícito fazer no sábado.",n:"O que se censura não é apanhar espigas alheias, que a Lei permitia ao faminto, mas fazê-lo no sábado: arrancar e esfregar contavam como colher e debulhar."},
{v:3,t:"Ele disse a eles: Não lestes o que fez Davi, quando teve fome, ele e os que estavam com ele?"},
{v:4,t:"Como entrou na casa de Deus e comeram os pães da proposição, que não lhe era lícito comer, nem aos que estavam com ele, mas só aos sacerdotes?"},
{v:5,t:"Ou não lestes na Lei que, nos sábados, os sacerdotes no Templo violam o sábado e ficam sem culpa?"},
{v:6,t:"Ora, eu vos digo que aqui está algo maior que o Templo."},
{v:7,t:"Se soubésseis o que significa: Misericórdia quero, e não sacrifício, não teríeis condenado os inocentes."},
{v:8,t:"Porque o Filho do Homem é senhor do sábado."},
{p:"Marcos 2:23-28"},
{v:23,t:"E aconteceu que ele passava, no sábado, pelas searas, e os seus discípulos começaram a abrir caminho, arrancando as espigas."},
{v:24,t:"Os fariseus diziam a ele: Vê, por que fazem no sábado o que não é lícito?"},
{v:25,t:"Ele disse a eles: Nunca lestes o que fez Davi, quando teve necessidade e sentiu fome, ele e os que estavam com ele?"},
{v:26,t:"Como entrou na casa de Deus, no tempo do sumo sacerdote Abiatar, e comeu os pães da proposição, que não é lícito comer senão aos sacerdotes, e deu também aos que estavam com ele?",n:"Em 1 Samuel 21 o sacerdote é Aquimelec, pai de Abiatar; a menção do filho, mais conhecido por acompanhar Davi, é modo antigo de indicar a passagem pelo nome da figura principal."},
{v:27,t:"E dizia a eles: O sábado foi feito por causa do homem, e não o homem por causa do sábado."},
{v:28,t:"Assim, o Filho do Homem é senhor até do sábado."},
{p:"Lucas 6:1-5"},
{v:1,t:"Aconteceu que, num sábado, passava ele pelas searas, e os seus discípulos arrancavam espigas e comiam, esfregando-as com as mãos."},
{v:2,t:"Alguns dos fariseus disseram: Por que fazeis o que não é lícito nos sábados?"},
{v:3,t:"Jesus respondeu: Não lestes o que fez Davi, quando teve fome, ele e os que estavam com ele?"},
{v:4,t:"Como entrou na casa de Deus, tomou os pães da proposição, comeu e deu aos que estavam com ele, embora não seja lícito comê-los senão só aos sacerdotes?"},
{v:5,t:"E dizia a eles: O Filho do Homem é senhor do sábado."}
];

EV[43] = [
{p:"Mateus 12:9-14"},
{v:9,t:"Partindo dali, foi à sinagoga deles."},
{v:10,t:"E eis um homem que tinha a mão seca; e perguntaram a ele: É lícito curar nos sábados? — para o acusarem."},
{v:11,t:"Ele disse a eles: Qual de vós, tendo uma só ovelha, se ela cair num poço no sábado, não a segurará e levantará?"},
{v:12,t:"Ora, quanto mais vale um homem do que uma ovelha! Portanto, é lícito fazer o bem nos sábados."},
{v:13,t:"Então disse ao homem: Estende a tua mão. Ele a estendeu, e ficou restituída, sã como a outra."},
{v:14,t:"Saindo, os fariseus fizeram conselho contra ele, sobre como o matariam."},
{p:"Marcos 3:1-6"},
{v:1,t:"Entrou de novo na sinagoga. Havia ali um homem que tinha a mão seca."},
{v:2,t:"E o observavam, para ver se o curaria no sábado, a fim de o acusarem."},
{v:3,t:"Ele disse ao homem que tinha a mão seca: Levanta-te para o meio."},
{v:4,t:"E disse a eles: É lícito, nos sábados, fazer o bem ou fazer o mal? Salvar uma vida ou matá-la? Eles, porém, calavam-se.",n:"A pergunta não deixa saída: quem se recusa a fazer o bem no dia santo já escolheu o outro termo. Enquanto calam, tramam a morte de Jesus, e é o que o v. 6 dirá."},
{v:5,t:"Olhando-os em redor com ira, contristado pela dureza do coração deles, disse ao homem: Estende a mão. Ele a estendeu, e a sua mão foi restituída."},
{v:6,t:"Saindo, os fariseus logo tomaram conselho com os herodianos contra ele, sobre como o matariam."},
{p:"Lucas 6:6-11"},
{v:6,t:"Aconteceu que, noutro sábado, entrou na sinagoga e ensinava. Havia ali um homem cuja mão direita estava seca."},
{v:7,t:"Os escribas e fariseus o observavam, para ver se curaria no sábado, a fim de acharem de que o acusar."},
{v:8,t:"Ele, porém, conhecia os pensamentos deles, e disse ao homem que tinha a mão seca: Levanta-te e fica de pé no meio. Ele se levantou e ficou de pé."},
{v:9,t:"Jesus disse a eles: Pergunto-vos: é lícito, no sábado, fazer o bem ou fazer o mal? Salvar uma vida ou perdê-la?"},
{v:10,t:"E, olhando a todos em redor, disse ao homem: Estende a tua mão. Ele o fez, e a sua mão foi restituída."},
{v:11,t:"Eles, porém, encheram-se de furor e discutiam entre si o que fariam a Jesus."}
];

EV[44] = [
{p:"Mateus 12:15-21"},
{v:15,t:"Sabendo disso, Jesus retirou-se dali. Muitos o seguiram, e ele curou a todos,"},
{v:16,t:"e ordenou a eles que não o tornassem manifesto,"},
{v:17,t:"para que se cumprisse o que foi dito pelo profeta Isaías:"},
{v:18,t:"Eis o meu servo, a quem escolhi; o meu amado, em quem a minha alma se comprazeu. Porei sobre ele o meu Espírito, e ele anunciará o julgamento às nações."},
{v:19,t:"Não contenderá nem gritará, nem alguém ouvirá a sua voz nas praças."},
{v:20,t:"Não quebrará a cana rachada, nem apagará o pavio que fumega, até que leve o julgamento à vitória;",n:"A cana rachada e o pavio que ainda fumega são figuras do que está quase a acabar: o Servo não remata o que se rompe, sustenta-o."},
{v:21,t:"e no seu nome esperarão as nações."},
{p:"Marcos 3:7-12"},
{v:7,t:"Jesus retirou-se com os seus discípulos para o mar, e uma grande multidão da Galileia o seguiu; também da Judeia,"},
{v:8,t:"de Jerusalém, da Idumeia, de além do Jordão e dos arredores de Tiro e Sidônia, uma grande multidão, ouvindo quanto fazia, veio a ele."},
{v:9,t:"E disse aos seus discípulos que lhe preparassem uma barquinha, por causa da multidão, para que não o comprimissem."},
{v:10,t:"Pois curou a muitos, de modo que se lançavam sobre ele, quantos tinham males, para o tocarem."},
{v:11,t:"E os espíritos impuros, quando o viam, prostravam-se diante dele e gritavam: Tu és o Filho de Deus."},
{v:12,t:"Mas ele os repreendia com severidade, para que não o tornassem manifesto."}
];

EV[45] = [
{p:"Marcos 3:13-19"},
{v:13,t:"Subiu ao monte e chamou a si os que ele quis; e foram a ele."},
{v:14,t:"Constituiu doze, aos quais deu o nome de apóstolos, para que estivessem com ele e para os enviar a pregar,",n:"Apóstolo quer dizer enviado. A ordem das duas finalidades não é indiferente: primeiro estar com ele, depois ser enviado."},
{v:15,t:"com poder de expulsar os demônios."},
{v:16,t:"Constituiu os doze: Simão, a quem pôs o nome de Pedro;"},
{v:17,t:"Tiago, filho de Zebedeu, e João, irmão de Tiago, aos quais pôs o nome de Boanerges, isto é, filhos do trovão;"},
{v:18,t:"André, Filipe, Bartolomeu, Mateus, Tomé, Tiago, filho de Alfeu, Tadeu, Simão, o Cananeu,",n:"Cananeu não indica aqui a terra de Canaã, mas verte o aramaico qanana, o zeloso; São Lucas traduz o mesmo epíteto por Zelote."},
{v:19,t:"e Judas Iscariotes, que o entregou."},
{p:"Lucas 6:12-16"},
{v:12,t:"Naqueles dias, saiu ao monte para orar, e passou a noite em oração a Deus."},
{v:13,t:"Sendo dia, chamou a si os seus discípulos e escolheu doze deles, aos quais também deu o nome de apóstolos:"},
{v:14,t:"Simão, a quem pôs o nome de Pedro, e André, seu irmão; Tiago e João; Filipe e Bartolomeu;"},
{v:15,t:"Mateus e Tomé; Tiago, filho de Alfeu, e Simão, chamado Zelote;"},
{v:16,t:"Judas, filho de Tiago, e Judas Iscariotes, que veio a ser o traidor."}
];

EV[46] = [
{p:"Mateus 5:1-48"},
{v:1,t:"Vendo as multidões, subiu ao monte; e, tendo-se sentado, os seus discípulos aproximaram-se dele.",n:"Sentar-se era a postura do mestre que ensina com autoridade; o monte evoca o Sinai, e quem ali fala não recebe a Lei, mas dá-lhe cumprimento."},
{v:2,t:"E, abrindo a boca, ensinava-os, dizendo:"},
{v:3,t:"Bem-aventurados os pobres em espírito, porque deles é o Reino dos céus.",n:"Pobres em espírito são os que nada têm de seu diante de Deus e disso não fazem queixa; a pobreza de que se fala é primeiro uma condição da alma, embora não dispense a outra."},
{v:4,t:"Bem-aventurados os que choram, porque serão consolados."},
{v:5,t:"Bem-aventurados os mansos, porque possuirão a terra.",n:"Retoma o Salmo 37: a terra prometida aos que não a arrancam pela força."},
{v:6,t:"Bem-aventurados os que têm fome e sede da justiça, porque serão saciados."},
{v:7,t:"Bem-aventurados os misericordiosos, porque alcançarão misericórdia."},
{v:8,t:"Bem-aventurados os puros de coração, porque verão a Deus."},
{v:9,t:"Bem-aventurados os pacíficos, porque serão chamados filhos de Deus.",n:"O grego eirenopoioi diz mais que viver em paz: designa quem a faz, quem a produz entre os que estavam desavindos."},
{v:10,t:"Bem-aventurados os que sofrem perseguição por causa da justiça, porque deles é o Reino dos céus."},
{v:11,t:"Bem-aventurados sois quando vos injuriarem e perseguirem e, mentindo, disserem todo mal contra vós por minha causa.",n:"Aqui o discurso passa da terceira à segunda pessoa: as bem-aventuranças deixam de descrever e voltam-se para quem escuta."},
{v:12,t:"Alegrai-vos e exultai, porque é grande a vossa recompensa nos céus; pois assim perseguiram os profetas que vieram antes de vós."},
{v:13,t:"Vós sois o sal da terra. Se o sal perder o sabor, com que se há de salgar? Para nada mais presta, senão para ser lançado fora e pisado pelos homens."},
{v:14,t:"Vós sois a luz do mundo. Não se pode esconder uma cidade situada sobre um monte."},
{v:15,t:"Nem se acende uma lâmpada para a pôr debaixo do alqueire, mas sobre o velador, e ela ilumina todos os que estão em casa.",n:"O alqueire era a vasilha de medir grão, que virada cobria a chama; o velador, o suporte alto em que a lâmpada alcançava toda a casa."},
{v:16,t:"Assim brilhe a vossa luz diante dos homens, para que vejam as vossas boas obras e glorifiquem o vosso Pai que está nos céus."},
{v:17,t:"Não penseis que vim revogar a Lei ou os Profetas; não vim revogar, mas dar cumprimento.",n:"Dar cumprimento verte plerosai, encher até à medida: não anular o que a Lei pedia, mas levá-lo ao termo que ela mesma anunciava."},
{v:18,t:"Pois em verdade vos digo: até que passem o céu e a terra, não passará da Lei um só i nem um só til, sem que tudo se cumpra.",n:"O iota era a menor letra do alfabeto grego, como o yod do hebraico; o til é o traço miúdo que distingue letras semelhantes. Diz-se assim: nem o menor sinal da escrita."},
{v:19,t:"Portanto, quem violar um destes mandamentos, mesmo o menor, e assim ensinar aos homens, será chamado o menor no Reino dos céus; mas quem os praticar e ensinar, esse será chamado grande no Reino dos céus."},
{v:20,t:"Pois eu vos digo: se a vossa justiça não exceder a dos escribas e fariseus, não entrareis no Reino dos céus."},
{v:21,t:"Ouvistes que foi dito aos antigos: Não matarás; e quem matar será réu de julgamento."},
{v:22,t:"Eu, porém, vos digo: todo o que se irar contra o seu irmão será réu de julgamento; quem disser ao seu irmão: Raca, será réu diante do Sinédrio; e quem lhe disser: Louco, será réu da geena do fogo.",n:"Raca é injúria aramaica, algo como cabeça oca. A geena é o vale de Hinom, junto a Jerusalém, onde outrora se queimavam crianças a Moloc e depois se queimava o lixo: tornou-se nome do castigo final."},
{v:23,t:"Portanto, se estiveres apresentando a tua oferta ao altar e ali te lembrares de que o teu irmão tem alguma coisa contra ti,"},
{v:24,t:"deixa ali a tua oferta diante do altar e vai primeiro reconciliar-te com o teu irmão; depois vem e apresenta a tua oferta.",n:"Note-se que não se trata do que tu tens contra ele, mas do que ele tem contra ti: a iniciativa cabe ao ofensor, e interrompe até o culto."},
{v:25,t:"Entra em acordo depressa com o teu adversário, enquanto estás com ele no caminho, para que o adversário não te entregue ao juiz, e o juiz ao guarda, e sejas lançado na prisão."},
{v:26,t:"Em verdade te digo: não sairás dali enquanto não pagares o último centavo."},
{v:27,t:"Ouvistes que foi dito: Não cometerás adultério."},
{v:28,t:"Eu, porém, vos digo: todo o que olha para uma mulher desejando-a já cometeu adultério com ela no seu coração."},
{v:29,t:"Se o teu olho direito te escandaliza, arranca-o e lança-o fora de ti; pois te convém que se perca um dos teus membros, e não que todo o teu corpo seja lançado na geena.",n:"Escandalizar traduz skandalizein, fazer tropeçar: a imagem é a da armadilha posta no caminho, não a do mero desgosto."},
{v:30,t:"E, se a tua mão direita te escandaliza, corta-a e lança-a fora de ti; pois te convém que se perca um dos teus membros, e não que todo o teu corpo vá para a geena."},
{v:31,t:"Foi dito também: Quem repudiar a sua mulher, dê-lhe carta de divórcio."},
{v:32,t:"Eu, porém, vos digo: todo o que repudia a sua mulher, exceto no caso de união ilegítima, a expõe ao adultério; e quem casar com a repudiada comete adultério.",n:"O termo grego porneia não designa aqui o adultério, que tem outro nome no mesmo versículo, mas uma união que nunca foi legítima; daí a tradução."},
{v:33,t:"Ouvistes ainda que foi dito aos antigos: Não jurarás falso, mas cumprirás ao Senhor os teus juramentos."},
{v:34,t:"Eu, porém, vos digo: não jureis de modo algum: nem pelo céu, porque é o trono de Deus;"},
{v:35,t:"nem pela terra, porque é o escabelo dos seus pés; nem por Jerusalém, porque é a cidade do grande Rei."},
{v:36,t:"Nem jurarás pela tua cabeça, porque não podes tornar um só cabelo branco ou preto."},
{v:37,t:"Seja o vosso falar: Sim, sim; não, não. O que passa disso vem do Maligno."},
{v:38,t:"Ouvistes que foi dito: Olho por olho e dente por dente.",n:"A lei antiga do talião já era um freio: media a vingança pelo dano, proibindo exceder-lhe. Jesus não a corrige por excessiva, mas leva além do que ela podia pedir."},
{v:39,t:"Eu, porém, vos digo: não resistais ao mau; mas, se alguém te bater na face direita, oferece-lhe também a outra."},
{v:40,t:"E ao que quiser demandar contigo para te tirar a túnica, deixa-lhe também o manto."},
{v:41,t:"E, se alguém te obrigar a caminhar mil passos, vai com ele dois mil.",n:"O verbo angareuein designa a requisição forçada que os soldados romanos podiam impor aos habitantes; a medida é a milha romana, mil passos."},
{v:42,t:"Dá a quem te pede, e não voltes as costas ao que deseja de ti um empréstimo."},
{v:43,t:"Ouvistes que foi dito: Amarás o teu próximo e odiarás o teu inimigo.",n:"A primeira metade está em Levítico 19; a segunda não se lê em parte alguma da Lei, e é a leitura corrente que Jesus recusa."},
{v:44,t:"Eu, porém, vos digo: amai os vossos inimigos e orai pelos que vos perseguem,"},
{v:45,t:"para que sejais filhos do vosso Pai que está nos céus; pois ele faz nascer o seu sol sobre maus e bons, e faz chover sobre justos e injustos."},
{v:46,t:"Se amardes os que vos amam, que recompensa tereis? Não fazem os publicanos também o mesmo?"},
{v:47,t:"E, se saudardes apenas os vossos irmãos, que fazeis de mais? Não fazem os gentios também o mesmo?"},
{v:48,t:"Sede, pois, perfeitos, como perfeito é o vosso Pai celeste.",n:"Perfeito traduz teleios, o que chegou ao seu fim e medida; não a impecabilidade, mas a inteireza de quem ama sem descontar ninguém, à maneira do Pai que faz nascer o sol sobre todos."},
{p:"Mateus 6:1-34"},
{v:1,t:"Guardai-vos de praticar a vossa justiça diante dos homens para serdes vistos por eles; do contrário, não tereis recompensa junto do vosso Pai que está nos céus.",n:"Justiça abrange aqui as três obras de piedade que o capítulo vai percorrer: a esmola, a oração e o jejum."},
{v:2,t:"Portanto, quando deres esmola, não toques trombeta diante de ti, como fazem os hipócritas nas sinagogas e nas ruas, para serem honrados pelos homens. Em verdade vos digo: já receberam a sua recompensa.",n:"Hipócrita era, no teatro grego, o ator que falava por trás de uma máscara; a palavra guarda essa imagem de quem representa um papel diante do público."},
{v:3,t:"Tu, porém, ao dares esmola, não saiba a tua mão esquerda o que faz a tua direita,"},
{v:4,t:"para que a tua esmola fique em segredo; e o teu Pai, que vê no segredo, te retribuirá."},
{v:5,t:"E, quando orardes, não sejais como os hipócritas, que gostam de orar de pé nas sinagogas e nas esquinas das praças, para serem vistos pelos homens. Em verdade vos digo: já receberam a sua recompensa."},
{v:6,t:"Tu, porém, quando orares, entra no teu quarto e, fechada a porta, ora ao teu Pai que está no segredo; e o teu Pai, que vê no segredo, te retribuirá."},
{v:7,t:"Orando, não useis de muitas palavras, como os gentios, que julgam ser ouvidos por muito falarem."},
{v:8,t:"Não sejais como eles, pois o vosso Pai sabe do que tendes necessidade antes que lho peçais."},
{v:9,t:"Vós, portanto, orai assim: Pai nosso, que estás nos céus, santificado seja o teu nome;"},
{v:10,t:"venha o teu Reino; seja feita a tua vontade, assim na terra como no céu."},
{v:11,t:"O pão nosso de cada dia dá-nos hoje;",n:"O adjetivo epiousios não aparece em nenhum outro texto grego conhecido antes deste. Pode entender-se como o pão necessário à subsistência, o pão de hoje ou o pão do dia que vem; a tradução corrente guarda a primeira leitura sem excluir as outras."},
{v:12,t:"e perdoa-nos as nossas dívidas, assim como nós perdoamos aos nossos devedores;",n:"São Mateus fala de dívidas, imagem semita do pecado como débito; São Lucas, ao referir a mesma oração, diz pecados."},
{v:13,t:"e não nos deixes cair em tentação, mas livra-nos do Maligno.",n:"O verbo grego é levar para dentro, e o pedido não supõe que Deus induza ao mal: pede-se que não nos abandone à prova quando ela chegar."},
{v:14,t:"Pois, se perdoardes aos homens as suas ofensas, também o vosso Pai celeste vos perdoará;"},
{v:15,t:"mas, se não perdoardes aos homens, tampouco o vosso Pai vos perdoará as vossas ofensas."},
{v:16,t:"Quando jejuardes, não vos mostreis tristes como os hipócritas, que desfiguram o rosto para parecer aos homens que jejuam. Em verdade vos digo: já receberam a sua recompensa."},
{v:17,t:"Tu, porém, quando jejuares, unge a tua cabeça e lava o teu rosto,"},
{v:18,t:"para não parecer aos homens que jejuas, mas ao teu Pai que está no segredo; e o teu Pai, que vê no segredo, te retribuirá."},
{v:19,t:"Não ajunteis para vós tesouros na terra, onde a traça e a ferrugem corroem, e onde os ladrões arrombam e roubam."},
{v:20,t:"Ajuntai para vós tesouros no céu, onde nem a traça nem a ferrugem corroem, e onde os ladrões não arrombam nem roubam."},
{v:21,t:"Pois onde está o teu tesouro, ali estará também o teu coração."},
{v:22,t:"A lâmpada do corpo é o olho. Se o teu olho for simples, todo o teu corpo será luminoso;",n:"Simples verte haplous, o que é de uma só peça, sem dobra nem segunda intenção; no falar da época dizia-se também do olhar generoso, que não cobiça."},
{v:23,t:"mas, se o teu olho for mau, todo o teu corpo será tenebroso. Se, pois, a luz que há em ti é trevas, quão grandes serão as trevas!"},
{v:24,t:"Ninguém pode servir a dois senhores; pois ou odiará um e amará o outro, ou se apegará a um e desprezará o outro. Não podeis servir a Deus e ao dinheiro.",n:"O texto conserva a palavra aramaica mamona, o bem acumulado em que se põe a segurança; ao pô-la em frente de Deus, Jesus trata-a como um senhor rival, quase um nome próprio."},
{v:25,t:"Por isso vos digo: não andeis ansiosos pela vossa vida, sobre o que haveis de comer; nem pelo vosso corpo, sobre o que haveis de vestir. Não é a vida mais do que o alimento, e o corpo mais do que a veste?",n:"Ansiosos traduz merimnan, o cuidado que divide e dilacera; não se condena a previdência, mas a inquietação que rouba a confiança."},
{v:26,t:"Olhai as aves do céu: não semeiam, nem ceifam, nem ajuntam em celeiros; e o vosso Pai celeste as alimenta. Não valeis vós muito mais do que elas?"},
{v:27,t:"Qual de vós, por mais que se inquiete, pode acrescentar um só côvado à sua estatura?",n:"As duas palavras são ambíguas: pode ler-se acrescentar um côvado à altura ou acrescentar um instante à duração da vida. A segunda leitura ajusta-se melhor ao contexto, mas a imagem material é a que o grego diz primeiro."},
{v:28,t:"E por que andais ansiosos com a veste? Considerai os lírios do campo, como crescem: não trabalham nem fiam."},
{v:29,t:"E eu vos digo que nem Salomão, em toda a sua glória, se vestiu como um deles."},
{v:30,t:"Ora, se Deus veste assim a erva do campo, que hoje existe e amanhã é lançada no forno, quanto mais a vós, homens de pouca fé!"},
{v:31,t:"Não andeis, pois, ansiosos, dizendo: Que comeremos? ou: Que beberemos? ou: Com que nos vestiremos?"},
{v:32,t:"Por todas essas coisas se afadigam os gentios; ora, o vosso Pai celeste sabe que de tudo isso tendes necessidade."},
{v:33,t:"Buscai primeiro o Reino de Deus e a sua justiça, e todas essas coisas vos serão acrescentadas."},
{v:34,t:"Não vos inquieteis, pois, pelo dia de amanhã; o dia de amanhã cuidará de si mesmo. Basta a cada dia o seu próprio mal."},
{p:"Mateus 7:1-29"},
{v:1,t:"Não julgueis, para que não sejais julgados."},
{v:2,t:"Pois com o julgamento com que julgardes sereis julgados, e com a medida com que medirdes vos medirão."},
{v:3,t:"Por que vês o argueiro no olho do teu irmão e não reparas na trave que está no teu?",n:"Argueiro é o fragmento miúdo de palha ou serradura; a trave é a viga que sustenta o telhado. O exagero é deliberado, e nele está o riso da parábola."},
{v:4,t:"Ou como dirás ao teu irmão: Deixa-me tirar o argueiro do teu olho, quando há uma trave no teu?"},
{v:5,t:"Hipócrita, tira primeiro a trave do teu olho, e então verás claro para tirar o argueiro do olho do teu irmão.",n:"A ordem não proíbe corrigir o irmão: manda começar por si, para enxergar o bastante e poder fazê-lo."},
{v:6,t:"Não deis aos cães o que é santo, nem lanceis as vossas pérolas diante dos porcos, para que não as pisem com os pés e, voltando-se, vos despedacem.",n:"O que é santo designa a carne oferecida em sacrifício, que não se atirava aos animais. Cão e porco eram, para o ouvinte judeu, os bichos impuros por excelência."},
{v:7,t:"Pedi, e vos será dado; buscai, e achareis; batei, e vos será aberto."},
{v:8,t:"Pois todo o que pede recebe; quem busca acha; e ao que bate se abrirá."},
{v:9,t:"Ou qual de vós é o homem que, se o filho lhe pedir pão, lhe dará uma pedra?"},
{v:10,t:"Ou, se lhe pedir um peixe, lhe dará uma serpente?"},
{v:11,t:"Se vós, pois, sendo maus, sabeis dar boas coisas aos vossos filhos, quanto mais o vosso Pai que está nos céus dará coisas boas aos que lhas pedirem!"},
{v:12,t:"Portanto, tudo quanto quereis que os homens vos façam, fazei-o também vós a eles; nisto está a Lei e os Profetas.",n:"A regra corria entre os antigos na forma negativa, não faças a outro o que não queres para ti; aqui vem em forma positiva, e pede iniciativa em lugar de abstenção."},
{v:13,t:"Entrai pela porta estreita; porque larga é a porta e espaçoso o caminho que leva à perdição, e muitos são os que entram por ela."},
{v:14,t:"Quão estreita é a porta e apertado o caminho que leva à vida, e poucos são os que o encontram!"},
{v:15,t:"Guardai-vos dos falsos profetas, que vêm a vós com vestes de ovelhas, mas por dentro são lobos vorazes."},
{v:16,t:"Pelos seus frutos os conhecereis. Colhem-se, porventura, uvas dos espinheiros, ou figos dos abrolhos?"},
{v:17,t:"Assim, toda árvore boa produz frutos bons, e a árvore má produz frutos maus."},
{v:18,t:"Não pode a árvore boa dar frutos maus, nem a árvore má dar frutos bons."},
{v:19,t:"Toda árvore que não dá bom fruto é cortada e lançada ao fogo."},
{v:20,t:"Portanto, pelos seus frutos os conhecereis."},
{v:21,t:"Nem todo o que me diz: Senhor, Senhor, entrará no Reino dos céus, mas aquele que faz a vontade de meu Pai que está nos céus."},
{v:22,t:"Muitos me dirão naquele dia: Senhor, Senhor, não profetizamos nós em teu nome, e em teu nome não expulsamos demônios, e em teu nome não fizemos muitos milagres?"},
{v:23,t:"E então lhes declararei: Nunca vos conheci; apartai-vos de mim, vós que praticais a iniquidade."},
{v:24,t:"Todo aquele, pois, que ouve estas minhas palavras e as põe em prática será comparado ao homem prudente que edificou a sua casa sobre a rocha."},
{v:25,t:"Caiu a chuva, vieram as torrentes, sopraram os ventos e investiram contra aquela casa; e ela não caiu, porque estava fundada sobre a rocha."},
{v:26,t:"E todo o que ouve estas minhas palavras e não as põe em prática será comparado ao homem insensato que edificou a sua casa sobre a areia."},
{v:27,t:"Caiu a chuva, vieram as torrentes, sopraram os ventos e arremeteram contra aquela casa; e ela caiu, e grande foi a sua ruína.",n:"As duas casas recebem a mesma tempestade: não se prometeu ao que ouve que a chuva o poupe, mas que o alicerce aguente."},
{v:28,t:"Quando Jesus acabou estas palavras, as multidões admiravam-se do seu ensino;"},
{v:29,t:"pois as ensinava como quem tem autoridade, e não como os seus escribas."},
{p:"Lucas 6:17-49"},
{v:17,t:"Descendo com eles, parou num lugar plano, com grande multidão dos seus discípulos e grande número de povo de toda a Judeia, de Jerusalém e da região litorânea de Tiro e Sidônia,",n:"Por este lugar plano se costuma chamar sermão da planície ao discurso de São Lucas, mais breve que o de São Mateus e dirigido de modo mais direto aos que escutam."},
{v:18,t:"que tinham vindo para o ouvir e para serem curados das suas doenças; e os atormentados por espíritos impuros eram curados."},
{v:19,t:"E toda a multidão procurava tocá-lo, porque saía dele uma força que curava a todos."},
{v:20,t:"Ele, levantando os olhos para os seus discípulos, dizia: Bem-aventurados vós, os pobres, porque vosso é o Reino de Deus.",n:"São Lucas diz os pobres, sem acrescentar em espírito: nele a bem-aventurança recai sobre a pobreza real, e a ela correspondem os ais dirigidos aos ricos."},
{v:21,t:"Bem-aventurados vós, que agora tendes fome, porque sereis saciados. Bem-aventurados vós, que agora chorais, porque haveis de rir."},
{v:22,t:"Bem-aventurados sereis quando os homens vos odiarem, e quando vos excluírem, insultarem e proscreverem o vosso nome como mau, por causa do Filho do Homem."},
{v:23,t:"Alegrai-vos naquele dia e exultai, porque é grande a vossa recompensa no céu; pois assim faziam os seus pais aos profetas."},
{v:24,t:"Mas ai de vós, ricos, porque já tendes a vossa consolação.",n:"O ai não é maldição, mas lamento: chora-se por quem já gastou em vida o que lhe cabia receber."},
{v:25,t:"Ai de vós, que agora estais fartos, porque haveis de ter fome. Ai de vós, que agora rides, porque haveis de lamentar e chorar."},
{v:26,t:"Ai de vós, quando todos os homens vos louvarem; pois assim faziam os seus pais aos falsos profetas."},
{v:27,t:"Mas a vós que me ouvis eu digo: amai os vossos inimigos, fazei o bem aos que vos odeiam;"},
{v:28,t:"bendizei os que vos amaldiçoam, orai pelos que vos difamam."},
{v:29,t:"Ao que te bater numa face, oferece também a outra; e ao que te tirar o manto, não recuses também a túnica."},
{v:30,t:"Dá a todo o que te pede; e ao que toma o que é teu, não o reclames."},
{v:31,t:"E, como quereis que os homens vos façam, fazei-lhes também vós do mesmo modo."},
{v:32,t:"Se amais os que vos amam, que agradecimento tereis? Pois também os pecadores amam os que os amam.",n:"Agradecimento verte charis, a mesma palavra que noutros lugares se traduz por graça: pergunta-se que favor há nisso, que mérito gratuito."},
{v:33,t:"E, se fizerdes o bem aos que vos fazem o bem, que agradecimento tereis? Também os pecadores fazem o mesmo."},
{v:34,t:"E, se emprestardes àqueles de quem esperais receber, que agradecimento tereis? Também os pecadores emprestam aos pecadores, para receberem outro tanto."},
{v:35,t:"Amai, porém, os vossos inimigos; fazei o bem e emprestai sem nada esperar; e será grande a vossa recompensa, e sereis filhos do Altíssimo, porque ele é bom para com os ingratos e maus."},
{v:36,t:"Sede misericordiosos, como o vosso Pai é misericordioso.",n:"Onde São Mateus conclui pedindo que sejamos perfeitos como o Pai, São Lucas diz misericordiosos: é a mesma exigência, dita pelo que nela há de mais próprio a Deus."},
{v:37,t:"Não julgueis, e não sereis julgados; não condeneis, e não sereis condenados; perdoai, e sereis perdoados."},
{v:38,t:"Dai, e será dado a vós: uma boa medida, calcada, sacudida, transbordante, será posta no vosso regaço; pois com a medida com que medirdes vos medirão.",n:"A imagem vem do mercado de grão: enchia-se a medida, calcava-se e sacudia-se para assentar, e ainda se deixava transbordar. O regaço é a dobra larga do manto, usada como bolsa."},
{v:39,t:"Disse-lhes também uma parábola: Pode um cego guiar outro cego? Não cairão ambos numa cova?"},
{v:40,t:"O discípulo não está acima do mestre; mas todo o que estiver bem formado será como o seu mestre."},
{v:41,t:"Por que vês o argueiro no olho do teu irmão e não reparas na trave que está no teu próprio olho?"},
{v:42,t:"Como podes dizer ao teu irmão: Irmão, deixa-me tirar o argueiro do teu olho, tu que não vês a trave no teu? Hipócrita, tira primeiro a trave do teu olho, e então verás claro para tirar o argueiro do olho do teu irmão."},
{v:43,t:"Não há árvore boa que dê fruto mau, nem árvore má que dê fruto bom."},
{v:44,t:"Cada árvore se conhece pelo seu próprio fruto; pois não se colhem figos dos espinheiros, nem se vindimam uvas da sarça."},
{v:45,t:"O homem bom, do bom tesouro do seu coração, tira o bem; e o mau, do mau, tira o mal; pois a boca fala do que transborda do coração."},
{v:46,t:"Por que me chamais: Senhor, Senhor, e não fazeis o que eu digo?"},
{v:47,t:"Todo o que vem a mim, ouve as minhas palavras e as põe em prática, eu vos mostrarei a quem é semelhante:"},
{v:48,t:"é semelhante ao homem que, edificando uma casa, cavou fundo e pôs o alicerce sobre a rocha. Vindo a enchente, a torrente arremeteu contra aquela casa e não conseguiu abalá-la, porque estava bem edificada.",n:"São Lucas insiste no cavar fundo, trabalho oculto e demorado; São Mateus opõe simplesmente a rocha à areia."},
{v:49,t:"Mas o que ouve e não põe em prática é semelhante ao homem que edificou a sua casa sobre a terra, sem alicerce; a torrente arremeteu contra ela, e logo caiu, e grande foi a ruína daquela casa."}
];

EV[47] = [
{p:"Mateus 8:5-13"},
{v:5,t:"Tendo ele entrado em Cafarnaum, aproximou-se dele um centurião, rogando-lhe"},
{v:6,t:"e dizendo: Senhor, o meu servo jaz em casa, paralítico, atrozmente atormentado."},
{v:7,t:"Disse a ele: Eu irei curá-lo."},
{v:8,t:"Mas o centurião respondeu: Senhor, não sou digno de que entres sob o meu teto; mas dize somente uma palavra, e o meu servo será curado.",n:"São estas as palavras que a Igreja repete antes da comunhão, mudando apenas o servo pela alma de quem as diz."},
{v:9,t:"Pois também eu sou homem sujeito a autoridade, e tenho soldados sob as minhas ordens; e digo a este: Vai, e ele vai; e a outro: Vem, e ele vem; e ao meu servo: Faze isto, e ele o faz.",n:"O centurião raciocina pelo que conhece: se a sua palavra, que é de homem sujeito a outros, basta para mover soldados à distância, quanto mais a de Jesus sobre a doença."},
{v:10,t:"Ouvindo isso, Jesus admirou-se e disse aos que o seguiam: Em verdade vos digo: em ninguém, em Israel, encontrei tamanha fé."},
{v:11,t:"E eu vos digo que muitos virão do oriente e do ocidente e se sentarão à mesa com Abraão, Isaac e Jacó no Reino dos céus;"},
{v:12,t:"mas os filhos do Reino serão lançados nas trevas exteriores; ali haverá pranto e ranger de dentes."},
{v:13,t:"E disse Jesus ao centurião: Vai; faça-se conforme creste. E naquela hora o servo ficou curado."},
{p:"Lucas 7:1-10"},
{v:1,t:"Quando acabou de dizer todas essas palavras aos ouvidos do povo, entrou em Cafarnaum."},
{v:2,t:"O servo de um centurião, que lhe era caro, estava mal e à morte."},
{v:3,t:"Tendo ouvido falar de Jesus, enviou a ele alguns anciãos dos judeus, rogando-lhe que viesse curar o seu servo.",n:"Em São Lucas o centurião não fala em pessoa: manda primeiro os anciãos, depois os amigos. A distância que guarda é a mesma que as suas palavras confessam."},
{v:4,t:"Chegando eles a Jesus, suplicavam com insistência, dizendo: Ele merece que lhe concedas isso,"},
{v:5,t:"pois ama a nossa nação, e ele mesmo nos edificou a sinagoga."},
{v:6,t:"Jesus foi com eles. E, quando já não estava longe da casa, o centurião enviou amigos a dizer a ele: Senhor, não te incomodes, pois não sou digno de que entres sob o meu teto;"},
{v:7,t:"por isso nem me julguei digno de ir ter contigo; mas dize uma palavra, e seja curado o meu servo."},
{v:8,t:"Pois também eu sou homem posto sob autoridade, e tenho soldados sob as minhas ordens; e digo a este: Vai, e ele vai; e a outro: Vem, e ele vem; e ao meu servo: Faze isto, e ele o faz."},
{v:9,t:"Ouvindo isso, Jesus admirou-se dele e, voltando-se para a multidão que o seguia, disse: Eu vos digo que nem em Israel encontrei tamanha fé."},
{v:10,t:"E, voltando a casa, os enviados encontraram o servo com saúde."}
];

EV[48] = [
{p:"Mateus 9:27-31"},
{v:27,t:"Partindo Jesus dali, seguiram-no dois cegos, gritando: Tem piedade de nós, Filho de Davi.",n:"Filho de Davi é título messiânico; são os cegos que primeiro o dão a Jesus em São Mateus, enquanto os que veem hesitam."},
{v:28,t:"Chegado a casa, os cegos vieram a ele; e Jesus disse a eles: Credes que posso fazer isso? Responderam: Sim, Senhor."},
{v:29,t:"Então tocou os olhos deles, dizendo: Faça-se convosco segundo a vossa fé."},
{v:30,t:"E os seus olhos se abriram. Jesus advertiu-os com severidade: Vede que ninguém o saiba."},
{v:31,t:"Eles, porém, saindo, divulgaram a sua fama por toda aquela terra."}
];

EV[49] = [
{p:"Mateus 9:32-34"},
{v:32,t:"Ao saírem eles, eis que trouxeram a ele um homem mudo, endemoninhado."},
{v:33,t:"Expulso o demônio, o mudo falou; e as multidões admiraram-se, dizendo: Nunca se viu tal coisa em Israel."},
{v:34,t:"Mas os fariseus diziam: É pelo príncipe dos demônios que ele expulsa os demônios.",n:"Diante do mesmo sinal, a multidão admira-se e os fariseus acusam; esta é a primeira formulação da calúnia que voltará no episódio de Belzebu."}
];

EV[50] = [
{p:"Mateus 9:35"},
{v:35,t:"E percorria Jesus todas as cidades e aldeias, ensinando nas suas sinagogas, pregando o Evangelho do Reino e curando toda doença e toda enfermidade."},
{p:"Lucas 8:1-3"},
{v:1,t:"Aconteceu depois que ele percorria cidades e aldeias, pregando e anunciando a Boa Nova do Reino de Deus; e com ele iam os Doze"},
{v:2,t:"e algumas mulheres que tinham sido curadas de espíritos maus e de enfermidades: Maria, chamada Madalena, da qual tinham saído sete demônios;"},
{v:3,t:"Joana, mulher de Cusa, procurador de Herodes; Susana e muitas outras, que os serviam com os seus bens.",n:"Que um mestre daquele tempo se fizesse acompanhar de mulheres era coisa sem exemplo; São Lucas guarda-lhes os nomes e diz que sustentavam o grupo com o que tinham."}
];

EV[51] = [
{p:"Lucas 7:11-17"},
{v:11,t:"Aconteceu depois que ele foi a uma cidade chamada Naim; e iam com ele os seus discípulos e uma grande multidão."},
{v:12,t:"Quando se aproximou da porta da cidade, eis que levavam um morto, filho único de sua mãe, e ela era viúva; e grande multidão da cidade ia com ela.",n:"Viúva e sem filho, a mulher ficava sem quem a sustentasse ou representasse; a perda não era só do afeto, mas de todo o amparo."},
{v:13,t:"Vendo-a, o Senhor compadeceu-se dela e disse a ela: Não chores.",n:"Ninguém pediu nada: é o único caso em que Jesus ressuscita alguém sem que a fé de outro o solicite. O motivo dado é apenas a compaixão."},
{v:14,t:"E, aproximando-se, tocou o esquife; os que o levavam pararam. E disse: Jovem, eu te digo, levanta-te."},
{v:15,t:"O morto sentou-se e começou a falar; e Jesus o entregou à sua mãe."},
{v:16,t:"O temor tomou a todos, e glorificavam a Deus, dizendo: Um grande profeta surgiu entre nós, e Deus visitou o seu povo."},
{v:17,t:"E essa palavra a seu respeito correu por toda a Judeia e por toda a região vizinha."}
];
